1	////////////////////////////////////////////////////////////////////////////////
2	//
3	// Filename:	rtl/core/pipemem.v
4	// {{{
5	// Project:	Zip CPU -- a small, lightweight, RISC CPU soft core
6	//
7	// Purpose:	A memory unit to support a CPU, this time one supporting
8	//		pipelined wishbone memory accesses.  The goal is to be able
9	//	to issue one pipelined wishbone access per clock, and (given the memory
10	//	is fast enough) to be able to read the results back at one access per
11	//	clock.  This renders on-chip memory fast enough to handle single cycle
12	//	(pipelined) access.
13	//
14	//
15	// Creator:	Dan Gisselquist, Ph.D.
16	//		Gisselquist Technology, LLC
17	//
18	////////////////////////////////////////////////////////////////////////////////
19	// }}}
20	// Copyright (C) 2015-2025, Gisselquist Technology, LLC
21	// {{{
22	// This program is free software (firmware): you can redistribute it and/or
23	// modify it under the terms of the GNU General Public License as published
24	// by the Free Software Foundation, either version 3 of the License, or (at
25	// your option) any later version.
26	//
27	// This program is distributed in the hope that it will be useful, but WITHOUT
28	// ANY WARRANTY; without even the implied warranty of MERCHANTIBILITY or
29	// FITNESS FOR A PARTICULAR PURPOSE.  See the GNU General Public License
30	// for more details.
31	//
32	// You should have received a copy of the GNU General Public License along
33	// with this program.  (It's in the $(ROOT)/doc directory.  Run make with no
34	// target there if the PDF file isn't present.)  If not, see
35	// <http://www.gnu.org/licenses/> for a copy.
36	// }}}
37	// License:	GPL, v3, as defined and found on www.gnu.org,
38	// {{{
39	//		http://www.gnu.org/licenses/gpl.html
40	//
41	////////////////////////////////////////////////////////////////////////////////
42	//
43	`default_nettype	none
44	// }}}
45	module	pipemem #(
46			// {{{
47			parameter	ADDRESS_WIDTH=28,
48			parameter	BUS_WIDTH=32,
49			parameter [0:0]	OPT_LOCK=1'b1,
50					WITH_LOCAL_BUS=1'b1,
51					OPT_ZERO_ON_IDLE=1'b0,
52					// OPT_ALIGNMENT_ERR
53					OPT_ALIGNMENT_ERR=1'b0,
54			localparam	AW=ADDRESS_WIDTH,
55					FLN=4,
56			parameter [(FLN-1):0]	OPT_MAXDEPTH=4'hd
57			// }}}
58		) (
59			// {{{
60			input	wire		i_clk, i_reset,
61			// CPU interface
62			// {{{
63			input	wire		i_pipe_stb, i_lock,
64			input	wire	[2:0]	i_op,
65			input	wire	[31:0]	i_addr,
66			input	wire	[31:0]	i_data,
67			input	wire	[4:0]	i_oreg,
68			// CPU outputs
69			output	wire		o_busy, o_rdbusy,
70			output	wire		o_pipe_stalled,
71			output	reg		o_valid,
72			output	reg		o_err,
73			output	reg	[4:0]	o_wreg,
74			output	reg	[31:0]	o_result,
75			// }}}
76			// Wishbone outputs
77			// {{{
78			output	wire			o_wb_cyc_gbl,
79			output	wire			o_wb_cyc_lcl,
80			output	reg			o_wb_stb_gbl,
81			output	reg			o_wb_stb_lcl, o_wb_we,
82			output	reg	[(AW-1):0]	o_wb_addr,
83			output	reg	[BUS_WIDTH-1:0]	o_wb_data,
84			output	reg [BUS_WIDTH/8-1:0]	o_wb_sel,
85			// Wishbone inputs
86			input	wire			i_wb_stall, i_wb_ack, i_wb_err,
87			input	wire	[BUS_WIDTH-1:0]	i_wb_data
88			// }}}
89			// }}}
90		);
91	
92		// Declarations
93		// {{{
94		localparam	WBLSB = $clog2(BUS_WIDTH/8);
95		// Verilator lint_off UNUSED
96		localparam	F_LGDEPTH=FLN+1;
97		// Verilator lint_on  UNUSED
98	`ifdef	FORMAL
99		wire	[(F_LGDEPTH-1):0]	f_nreqs, f_nacks, f_outstanding;
100		reg	f_pc;
101	`endif
102	
103		reg				cyc, r_wb_cyc_gbl, r_wb_cyc_lcl,
104						fifo_full;
105		wire				gbl_stb, lcl_stb, lcl_bus;
106		reg	[(FLN-1):0]		rdaddr, wraddr;
107		wire	[(FLN-1):0]		nxt_rdaddr, fifo_fill;
108		reg	[4+2+WBLSB-1:0]	fifo_mem [0:15];
109		reg					fifo_gie;
110		wire	[4+2+WBLSB-1:0]	w_wreg;
111		wire					misaligned;
112	
113		reg	[BUS_WIDTH/8-1:0]	oword_sel;
114		wire	[BUS_WIDTH/8-1:0]	pre_wb_sel;
115		reg	[31:0]			oword_data;
116		wire	[BUS_WIDTH-1:0]		pre_wb_data, pre_result;
117		// }}}
118	
119		// misaligned
120		// {{{
121		generate if (OPT_ALIGNMENT_ERR)
122		begin : GEN_ALIGNMENT_ERR
123			reg	r_mis;
124	
125			always	@(*)
126			casez({ i_op[2:1], i_addr[1:0] })
127			4'b01?1: r_mis = i_pipe_stb;
128			4'b0110: r_mis = i_pipe_stb;
129			4'b10?1: r_mis = i_pipe_stb;
130			default: r_mis = i_pipe_stb;
131			endcase
132	
133			assign	misaligned = r_mis;
134	
135		end else begin : NO_MISALIGNMENT_ERRS
136	
137			assign	misaligned = 1'b0;
138	
139		end endgenerate
140		// }}}
141	
142		// fifo_mem
143		// {{{
144		always @(posedge i_clk)
145			fifo_mem[wraddr] <= { i_oreg[3:0], i_op[2:1], i_addr[WBLSB-1:0] };
146		// }}}
147	
148		// fifo_gie
149		// {{{
150		always @(posedge i_clk)
151		if (i_pipe_stb)
152			fifo_gie <= i_oreg[4];
153		// }}}
154	
155		// wraddr
156		// {{{
157		initial	wraddr = 0;
158		always @(posedge i_clk)
159		if (i_reset)
160			wraddr <= 0;
161		else if (((i_wb_err)&&(cyc))||((i_pipe_stb)&&(misaligned)))
162				wraddr <= 0;
163		else if (i_pipe_stb)
164			wraddr <= wraddr + 1'b1;
165		// }}}
166	
167		// rdaddr
168		// {{{
169		initial	rdaddr = 0;
170		always @(posedge i_clk)
171		if (i_reset)
172			rdaddr <= 0;
173		else if (((i_wb_err)&&(cyc))||((i_pipe_stb)&&(misaligned)))
174			rdaddr <= 0;
175		else if ((i_wb_ack)&&(cyc))
176			rdaddr <= rdaddr + 1'b1;
177		// }}}
178	
179		assign	fifo_fill = wraddr - rdaddr;
180	
181		// fifo_full
182		// {{{
183		initial	fifo_full = 0;
184		always @(posedge i_clk)
185		if (i_reset || !cyc)
186			fifo_full <= 0;
187		else if (((i_wb_err)&&(cyc))||((i_pipe_stb)&&(misaligned)))
188			fifo_full <= 0;
189		else case({ i_pipe_stb, i_wb_ack })
190		2'b10: fifo_full <= (fifo_fill >= OPT_MAXDEPTH-1);
191		2'b01: fifo_full <= 1'b0;
192		default: begin end
193		endcase
194	`ifdef	FORMAL
195		always @(*)
196		if (!cyc)
197		begin
198			assert(fifo_full == 0);
199		end else
200			assert(fifo_full == (fifo_fill >= OPT_MAXDEPTH));
201	
202		always @(*)
203		if (fifo_full)
204			assert(fifo_fill == OPT_MAXDEPTH);
205	`endif
206		// }}}
207	
208		assign	nxt_rdaddr = rdaddr + 1'b1;
209	
210		// lcl_bus, lcl_stb, gbl_stb
211		// {{{
212		assign	lcl_bus = (i_addr[31:24]==8'hff)&&(WITH_LOCAL_BUS);
213		assign	lcl_stb = (lcl_bus)&&(!misaligned);
214		assign	gbl_stb = ((!lcl_bus)||(!WITH_LOCAL_BUS))&&(!misaligned);
215				//= ((i_addr[31:8]!=24'hc00000)||(i_addr[7:5]!=3'h0));
216		// }}}
217	
218		// cyc, [or]_wb_[cyc|stb]_[lcl|gbl]
219		// {{{
220		initial	cyc = 0;
221		initial	r_wb_cyc_lcl = 0;
222		initial	r_wb_cyc_gbl = 0;
223		initial	o_wb_stb_lcl = 0;
224		initial	o_wb_stb_gbl = 0;
225		always @(posedge i_clk)
226		begin
227			if (cyc)
228			begin
229				if (((!i_wb_stall)&&(!i_pipe_stb)&&(!misaligned))
230					||(i_wb_err))
231				begin
232					o_wb_stb_gbl <= 1'b0;
233					o_wb_stb_lcl <= 1'b0;
234				end
235	
236				if (((i_wb_ack)&&(nxt_rdaddr == wraddr)
237						&&((!i_pipe_stb)||(misaligned)))
238					||(i_wb_err))
239				begin
240					r_wb_cyc_gbl <= 1'b0;
241					r_wb_cyc_lcl <= 1'b0;
242					o_wb_stb_gbl <= 1'b0;
243					o_wb_stb_lcl <= 1'b0;
244					cyc <= 1'b0;
245				end
246			end else if (i_pipe_stb) // New memory operation
247			begin // Grab the wishbone
248				r_wb_cyc_lcl <= lcl_stb;
249				r_wb_cyc_gbl <= gbl_stb;
250				o_wb_stb_lcl <= lcl_stb;
251				o_wb_stb_gbl <= gbl_stb;
252				cyc <= (!misaligned);
253			end
254	
255			if (i_reset)
256			begin
257				r_wb_cyc_gbl <= 1'b0;
258				r_wb_cyc_lcl <= 1'b0;
259				o_wb_stb_gbl <= 1'b0;
260				o_wb_stb_lcl <= 1'b0;
261				cyc <= 1'b0;
262			end
263	
264			if (!WITH_LOCAL_BUS)
265			begin
266				r_wb_cyc_lcl <= 1'b0;
267				o_wb_stb_lcl <= 1'b0;
268			end
269		end
270		// }}}
271	
272		// pre_wb_sel
273		// {{{
274		always @(*)
275		begin
276			oword_sel = 0;
277			casez({ i_op[2:1], i_addr[1:0] })
278			4'b100?: oword_sel[3:0] = 4'b1100;	// Op = 5
279			4'b101?: oword_sel[3:0] = 4'b0011;	// Op = 5
280			4'b1100: oword_sel[3:0] = 4'b1000;	// Op = 5
281			4'b1101: oword_sel[3:0] = 4'b0100;	// Op = 7
282			4'b1110: oword_sel[3:0] = 4'b0010;	// Op = 7
283			4'b1111: oword_sel[3:0] = 4'b0001;	// Op = 7
284			default: oword_sel[3:0] = 4'b1111;	// Op = 7
285			endcase
286		end
287	
288		generate if (BUS_WIDTH == 32)
289		begin : GEN_SEL32
290	
291			assign	pre_wb_sel = oword_sel;
292	
293		end else begin : GEN_WIDESEL32
294	
295			// If we were little endian, we'd do ...
296			// assign	pre_wb_sel = (oword_sel << (4* i_addr[WBLSB-1:2]));
297			assign	pre_wb_sel = {oword_sel[3:0], {(BUS_WIDTH/8-4){1'b0}} }
298					>> (4* i_addr[WBLSB-1:2]);
299	
300		end endgenerate
301		// }}}
302	
303		// pre_wb_data
304		// {{{
305	
306		always @(*)
307		casez({ i_op[2:1], i_addr[1:0] })
308		4'b100?: oword_data = { i_data[15:0], 16'h00 };
309		4'b101?: oword_data = { 16'h00, i_data[15:0] };
310		4'b1100: oword_data = {         i_data[7:0], 24'h00 };
311		4'b1101: oword_data = {  8'h00, i_data[7:0], 16'h00 };
312		4'b1110: oword_data = { 16'h00, i_data[7:0],  8'h00 };
313		4'b1111: oword_data = { 24'h00, i_data[7:0] };
314		default: oword_data = i_data;
315		endcase
316	
317		generate if (BUS_WIDTH == 32)
318		begin : GEN_DATA32
319	
320			assign	pre_wb_data = oword_data;
321	
322		end else begin : GEN_WIDEDATA32
323	
324			// If we were little endian, we'd do ...
325			// assign	pre_wb_sel = (word_sel << (4* i_addr[WBLSB-1:2]));
326			assign	pre_wb_data = {oword_data, {(BUS_WIDTH-32){1'b0}} }
327					>> (32* i_addr[WBLSB-1:2]);
328	
329		end endgenerate
330		// }}}
331	
332		// o_wb_addr, o_wb_sel, and o_wb_data
333		// {{{
334		always @(posedge i_clk)
335		if ((!cyc)||(!i_wb_stall))
336		begin
337			// o_wb_add
338			// {{{
339			if ((OPT_ZERO_ON_IDLE)&&(!i_pipe_stb))
340				o_wb_addr <= 0;
341			else if (lcl_bus)
342				o_wb_addr <= i_addr[2 +: AW];
343			else
344				o_wb_addr <= i_addr[WBLSB +: AW];
345			// }}}
346	
347			// o_wb_sel
348			// {{{
349			if ((OPT_ZERO_ON_IDLE)&&(!i_pipe_stb))
350				o_wb_sel <= {(BUS_WIDTH/8){1'b0}};
351			else if (lcl_bus)
352				o_wb_sel <= oword_sel;
353			else
354				o_wb_sel <= pre_wb_sel;
355			// }}}
356	
357			// o_wb_data
358			// {{{
359			o_wb_data <= 0;
360			if ((OPT_ZERO_ON_IDLE)&&(!i_pipe_stb))
361				o_wb_data <= 0;
362			else if (lcl_bus)
363				o_wb_data[31:0] <= oword_data;
364			else
365				o_wb_data <= pre_wb_data;
366			// }}}
367		end
368		// }}}
369	
370		// o_wb_we
371		// {{{
372		always @(posedge i_clk)
373		if ((i_pipe_stb)&&(!cyc))
374			o_wb_we   <= i_op[0];
375		else if ((OPT_ZERO_ON_IDLE)&&(!cyc))
376			o_wb_we   <= 1'b0;
377		// }}}
378	
379		// o_valid
380		// {{{
381		initial	o_valid = 1'b0;
382		always @(posedge i_clk)
383		if (i_reset)
384			o_valid <= 1'b0;
385		else
386			o_valid <= (cyc)&&(i_wb_ack)&&(!o_wb_we);
387		// }}}
388	
389		// o_err
390		// {{{
391		initial	o_err = 1'b0;
392		always @(posedge i_clk)
393		if (i_reset)
394			o_err <= 1'b0;
395		else
396			o_err <= ((cyc)&&(i_wb_err))||((i_pipe_stb)&&(misaligned));
397		// }}}
398	
399		assign	o_busy = cyc;
400		assign	o_rdbusy = o_busy && !o_wb_we;
401	
402		assign	w_wreg = fifo_mem[rdaddr];
403	
404		// o_wreg
405		// {{{
406		always @(posedge i_clk)
407			o_wreg <= { fifo_gie, w_wreg[2 + WBLSB +: 4] };
408		// }}}
409	
410		// o_result
411		// {{{
412		generate if (BUS_WIDTH == 32)
413		begin : COPY_IDATA
414	
415			assign	pre_result = i_wb_data;
416	
417		end else begin : GEN_PRERESULT
418	
419			assign	pre_result = i_wb_data << (8*w_wreg[WBLSB-1:0]);
420			// Verilator coverage_off
421			// Verilator lint_off UNUSED
422			wire	unused_preresult;
423			assign	unused_preresult = &{1'b0, pre_result[BUS_WIDTH-33:0] };
424			// Verilator lint_on  UNUSED
425			// Verilator coverage_on
426		end endgenerate
427	
428		always @(posedge i_clk)
429		if ((OPT_ZERO_ON_IDLE)&&((!cyc)||((!i_wb_ack)&&(!i_wb_err))))
430			o_result <= 0;
431		else if ((o_wb_cyc_lcl && WITH_LOCAL_BUS) || (BUS_WIDTH == 32))
432		begin
433			casez({ w_wreg[WBLSB +: 2], w_wreg[1:0] })
434			4'b1100: o_result <= { 24'h00, i_wb_data[31:24] };
435			4'b1101: o_result <= { 24'h00, i_wb_data[23:16] };
436			4'b1110: o_result <= { 24'h00, i_wb_data[15: 8] };
437			4'b1111: o_result <= { 24'h00, i_wb_data[ 7: 0] };
438			4'b100?: o_result <= { 16'h00, i_wb_data[31:16] };
439			4'b101?: o_result <= { 16'h00, i_wb_data[15: 0] };
440			default: o_result <= i_wb_data[31:0];
441			endcase
442		end else begin
443			casez(w_wreg[WBLSB +: 2])
444			2'b11: o_result <= { 24'h00, pre_result[BUS_WIDTH-1:BUS_WIDTH-8] };
445			2'b10: o_result <= { 16'h00, pre_result[BUS_WIDTH-1:BUS_WIDTH-16] };
446			default: o_result <= pre_result[BUS_WIDTH-1:BUS_WIDTH-32];
447			endcase
448		end
449		// }}}
450	
451		// o_pipe_stalled
452		// {{{
453		assign	o_pipe_stalled = ((cyc)&&(fifo_full))||((cyc)
454				&&((i_wb_stall)||((!o_wb_stb_lcl)&&(!o_wb_stb_gbl))));
455		// }}}
456	
457		// lock_gbl, lock_lcl
458		// {{{
459		generate
460		if (OPT_LOCK)
461		begin : LOCK_REGISTER
462			// {{{
463			reg	lock_gbl, lock_lcl;
464	
465			initial	lock_gbl = 1'b0;
466			initial	lock_lcl = 1'b0;
467			always @(posedge i_clk)
468			begin
469				lock_gbl <= r_wb_cyc_gbl || lock_gbl;
470				lock_lcl <= r_wb_cyc_lcl || lock_lcl;
471	
472				if (i_reset || (i_wb_err && cyc)
473					|| (i_pipe_stb && misaligned)
474					|| !i_lock)
475				begin
476					lock_gbl <= 1'b0;
477					lock_lcl <= 1'b0;
478				end
479	
480				if (!WITH_LOCAL_BUS)
481					lock_lcl <= 1'b0;
482			end
483	
484			assign	o_wb_cyc_gbl = (r_wb_cyc_gbl)||(lock_gbl);
485			assign	o_wb_cyc_lcl = (r_wb_cyc_lcl)||(lock_lcl);
486			// }}}
487		end else begin : NO_LOCK
488			// {{{
489			assign	o_wb_cyc_gbl = (r_wb_cyc_gbl);
490			assign	o_wb_cyc_lcl = (r_wb_cyc_lcl);
491	
492			// Verilator coverage_off
493			// verilator lint_off UNUSED
494			wire	unused_lock;
495			assign	unused_lock = &{ 1'b0, i_lock };
496			// verilator lint_on  UNUSED
497			// Verilator coverage_on
498			// }}}
499		end endgenerate
500		// }}}
501	
502		// Make verilator happy
503		// {{{
504		// Verilator coverage_off
505		// verilator lint_off UNUSED
506		wire	unused;
507		assign	unused = { 1'b0 };
508		// verilator lint_on  UNUSED
509		// Verilator coverage_on
510		// }}}
511	////////////////////////////////////////////////////////////////////////////////
512	////////////////////////////////////////////////////////////////////////////////
513	////////////////////////////////////////////////////////////////////////////////
514	//
515	// Formal property section
516	// {{{
517	////////////////////////////////////////////////////////////////////////////////
518	////////////////////////////////////////////////////////////////////////////////
519	////////////////////////////////////////////////////////////////////////////////
520	`ifdef	FORMAL
521		// Declarations
522		// {{{
523	`define	ASSERT	assert
524	`ifdef	PIPEMEM
525	`define	ASSUME	assume
526	`else
527	`define	ASSUME	assert
528	`endif
529		wire	[(F_LGDEPTH-1):0]	fcpu_outstanding;
530		wire				f_cyc, f_stb;
531		reg				f_done;
532		wire	[3:0]			f_pipe_used;
533		reg	[(1<<FLN)-1:0]		f_mem_used;
534		reg				f_past_valid;
535		wire				f_pc_check, f_gie, f_read_cycle;
536		wire	[4:0]			f_last_reg, f_addr_reg;
537		// Verilator lint_off UNDRIVEN
538		(* anyseq *) reg	[4:0]	f_areg;
539		// Verilator lint_on  UNDRIVEN
540		// }}}
541		////////////////////////////////////////////////////////////////////////
542		//
543		// Reset properties
544		// {{{
545		////////////////////////////////////////////////////////////////////////
546		//
547		//
548		initial	f_past_valid = 0;
549		always @(posedge i_clk)
550			f_past_valid <= 1'b1;
551	
552		initial	`ASSUME( i_reset);
553		always @(*)
554		if (!f_past_valid)
555			`ASSUME(i_reset);
556		// }}}
557		////////////////////////////////////////////////////////////////////////
558		//
559		// Bus properties
560		// {{{
561		////////////////////////////////////////////////////////////////////////
562		//
563		//
564	
565		assign	f_cyc = cyc;
566		assign	f_stb = (o_wb_stb_gbl)||(o_wb_stb_lcl);
567	
568		fwb_master #(
569			// {{{
570			.AW(AW), .DW(BUS_WIDTH), .F_LGDEPTH(F_LGDEPTH),
571			// .F_MAX_REQUESTS(14), // Not quite true, can do more
572			.F_OPT_RMW_BUS_OPTION(OPT_LOCK),
573			.F_OPT_DISCONTINUOUS(OPT_LOCK)
574			// }}}
575		) fwb(
576			// {{{
577			i_clk, i_reset,
578			cyc, f_stb, o_wb_we, o_wb_addr, o_wb_data, o_wb_sel,
579				i_wb_ack, i_wb_stall, i_wb_data, i_wb_err,
580			f_nreqs, f_nacks, f_outstanding
581			// }}}
582		);
583	
584		// }}}
585		////////////////////////////////////////////////////////////////////////
586		//
587		// CPU interface properties
588		// {{{
589		////////////////////////////////////////////////////////////////////////
590		//
591		//
592		initial	f_done = 0;
593		always @(posedge i_clk)
594		if (i_reset)
595			f_done <= 1'b0;
596		else if (cyc)
597		begin
598			f_done <= 0;
599			if (i_wb_err || i_wb_ack)
600				f_done <= 1;
601			if (i_pipe_stb && misaligned)
602				f_done <= 1;
603		end else
604			f_done <= 1'b0;
605	
606		fmem #(
607			// {{{
608			.OPT_LOCK(OPT_LOCK),
609			.F_LGDEPTH(F_LGDEPTH),
610			.OPT_MAXDEPTH(OPT_MAXDEPTH)
611			// }}}
612		) iface(
613			// {{{
614			.i_clk(i_clk),
615			.i_sys_reset(i_reset),
616			.i_cpu_reset(i_reset),
617			.i_stb(i_pipe_stb),
618			.i_pipe_stalled(o_pipe_stalled),
619			.i_clear_cache(1'b0),
620			.i_lock(i_lock),
621			.i_op(i_op), .i_addr(i_addr), .i_data(i_data), .i_oreg(i_oreg),
622			.i_areg(f_areg),
623			.i_busy(o_busy), .i_rdbusy(o_busy && !o_wb_we),
624			.i_valid(o_valid), .i_done(f_done),
625				.i_err(o_err), .i_wreg(o_wreg), .i_result(o_result),
626				.f_outstanding(fcpu_outstanding),
627				.f_pc(f_pc_check), .f_gie(f_gie),
628				.f_read_cycle(f_read_cycle),
629				.f_last_reg(f_last_reg), .f_addr_reg(f_addr_reg)
630			// }}}
631		);
632	
633		always @(*)
634		if (!o_err || !OPT_ALIGNMENT_ERR)
635			assert(f_pc == f_pc_check);
636	
637		always @(*)
638		if (o_busy)
639			assert(f_gie == fifo_gie);
640	
641		always @(*)
642		if (cyc)
643			assert(f_read_cycle == !o_wb_we);
644	
645		// }}}
646		////////////////////////////////////////////////////////////////////////
647		//
648		// Other (induction) properties
649		// {{{
650		////////////////////////////////////////////////////////////////////////
651		//
652		//
653	
654		//
655		// Assumptions about inputs
656		//
657		always @(posedge i_clk)
658		if ((!f_past_valid)||($past(i_reset)))
659			`ASSERT(!o_pipe_stalled);
660	
661		// Assume we won't cross from GBL to LCL in a given string
662		// {{{
663		always @(posedge i_clk)
664		if ((r_wb_cyc_gbl)&&(i_pipe_stb))
665			`ASSUME(gbl_stb);
666	
667		always @(posedge i_clk)
668		if ((r_wb_cyc_lcl)&&(i_pipe_stb))
669			`ASSUME(lcl_stb);
670		// }}}
671	
672		assign	f_pipe_used = wraddr - rdaddr;
673	
674		always @(*)
675			`ASSERT(f_pipe_used == fifo_fill);
676	
677		always @(*)
678		if (!o_err)
679			`ASSERT(f_pipe_used + (f_done ? 1:0) == fcpu_outstanding);
680	
681		always @(posedge i_clk)
682		if (f_pipe_used == OPT_MAXDEPTH)
683		begin
684			// `ASSUME(!i_pipe_stb);
685			`ASSERT((o_busy)&&(o_pipe_stalled));
686		end
687	
688		always @(*)
689			`ASSERT(fifo_fill <= OPT_MAXDEPTH);
690	
691	`ifndef	VERILATOR
692		always @(*)
693		if ((WITH_LOCAL_BUS)&&(o_wb_cyc_gbl|o_wb_cyc_lcl)
694			&&(i_pipe_stb))
695		begin
696			if (o_wb_cyc_lcl)
697			begin
698				// `ASSUME(i_addr[31:24] == 8'hff);
699				assume(i_addr[31:24] == 8'hff);
700			end else
701				assume(i_addr[31:24] != 8'hff);
702		end
703	`endif
704	
705		always @(*)
706		if (!WITH_LOCAL_BUS)
707		begin
708			assert(!r_wb_cyc_lcl);
709			assert(!o_wb_cyc_lcl);
710			assert(!o_wb_stb_lcl);
711		end
712	
713		always @(posedge i_clk)
714		if ((f_past_valid)&&(!$past(f_cyc))&&(!$past(i_pipe_stb)))
715			`ASSERT(f_pipe_used == 0);
716	
717		always @(*)
718		if (!f_cyc)
719			`ASSERT(f_pipe_used == 0);
720	
721		always @(posedge i_clk)
722		if (f_pipe_used >= 13)
723			`ASSUME(!i_pipe_stb);
724	
725		always @(posedge i_clk)
726		if ((f_cyc)&&(f_pipe_used >= 13))
727			`ASSERT((o_busy)&&(o_pipe_stalled));
728	
729	
730		always @(posedge i_clk)
731			`ASSERT((!r_wb_cyc_gbl)||(!r_wb_cyc_lcl));
732	
733		always @(posedge i_clk)
734			`ASSERT((!o_wb_cyc_gbl)||(!o_wb_cyc_lcl));
735	
736		always @(posedge i_clk)
737			`ASSERT((!o_wb_stb_gbl)||(!o_wb_stb_lcl));
738	
739		always @(*)
740		if (!WITH_LOCAL_BUS)
741		begin
742			assert(!o_wb_cyc_lcl);
743			assert(!o_wb_stb_lcl);
744			if (o_wb_stb_lcl)
745				assert(o_wb_addr[(AW-1):22] == {(8-(30-AW)){1'b1}});
746		end
747	
748		always @(posedge i_clk)
749		if (o_wb_stb_gbl)
750			`ASSERT(o_wb_cyc_gbl);
751	
752		always @(posedge i_clk)
753		if (o_wb_stb_lcl)
754			`ASSERT(o_wb_cyc_lcl);
755	
756		always @(posedge i_clk)
757			`ASSERT(cyc == (r_wb_cyc_gbl|r_wb_cyc_lcl));
758	
759		always @(posedge i_clk)
760			`ASSERT(cyc == (r_wb_cyc_lcl)|(r_wb_cyc_gbl));
761	
762		always @(posedge i_clk)
763		if ((f_past_valid)&&(!i_reset)&&(!$past(misaligned)))
764		begin
765			if (f_stb)
766			begin
767				`ASSERT(f_pipe_used == f_outstanding + 4'h1);
768			end else
769				`ASSERT(f_pipe_used == f_outstanding);
770		end
771	
772		always @(posedge i_clk)
773		if ((f_past_valid)&&($past(r_wb_cyc_gbl||r_wb_cyc_lcl))
774				&&(!$past(f_stb)))
775			`ASSERT(!f_stb);
776	
777		always @(*)
778			`ASSERT((!lcl_stb)||(!gbl_stb));
779	
780		//
781		// insist that we only ever accept memory requests for the same GIE
782		// (i.e. 4th bit of register)
783		//
784		always @(*)
785		if ((i_pipe_stb)&&(wraddr != rdaddr))
786			`ASSUME(i_oreg[4] == fifo_gie);
787	
788		initial	f_pc = 1'b0;
789		always @(posedge i_clk)
790		if(i_reset)
791			f_pc <= 1'b0;
792		else if (i_pipe_stb && !misaligned)
793			f_pc <= (((f_pc)&&(f_cyc))
794					||((!i_op[0])&&(i_oreg[3:1] == 3'h7)));
795		else if (!f_cyc)
796			f_pc <= 1'b0;
797	
798		always @(posedge i_clk)
799		if ((f_cyc)&&(o_wb_we))
800			`ASSERT(!f_pc);
801	
802	//	always @(*)
803	//	if ((f_pc)&&(f_cyc))
804	//		`ASSUME(!i_pipe_stb);
805	
806		always @(*)
807		if (wraddr == rdaddr)
808		begin
809			`ASSERT(!r_wb_cyc_gbl);
810			`ASSERT(!r_wb_cyc_lcl);
811		end else if (f_cyc)
812		begin
813			`ASSERT(fifo_fill == f_outstanding + ((f_stb)?1:0));
814		end
815		// }}}
816		////////////////////////////////////////////////////////////////////////
817		//
818		// The FIFO check
819		// {{{
820		////////////////////////////////////////////////////////////////////////
821		//
822	
823	`define	FIFOCHECK
824	`ifdef	FIFOCHECK
825		reg	[4+2+WBLSB-1:0]	fc_mem, frd_mem;
826		// Verilator lint_off UNDRIVEN
827		(* anyconst *)	reg	[3:0]	fc_addr;
828		// Verilator lint_on  UNDRIVEN
829	
830		wire	[3:0]	lastaddr = wraddr - 1'b1;
831	
832		integer	k;
833		always @(*)
834		begin
835			f_mem_used = 0;
836			for(k = 0 ; k < (1<<FLN); k=k+1)
837			begin
838				if (wraddr == rdaddr)
839					f_mem_used[k] = 1'b0;
840				else if (wraddr > rdaddr)
841				begin
842					if ((k < wraddr)&&(k >= rdaddr))
843						f_mem_used[k] = 1'b1;
844				end else if (k < wraddr)
845					f_mem_used[k] = 1'b1;
846				else if (k >= rdaddr)
847					f_mem_used[k] = 1'b1;
848			end
849		end
850	
851		always @(*)
852			fc_mem = fifo_mem[fc_addr];
853		always @(*)
854			frd_mem = fifo_mem[rdaddr];
855	
856		always @(*)
857		if (cyc && !o_wb_we)
858		begin
859			if (f_mem_used[rdaddr] && fc_addr != rdaddr)
860			begin
861				assume((frd_mem[1+2+WBLSB +: 3] == 3'h7)
862					== (f_pc && rdaddr == lastaddr));
863				assume(({ fifo_gie, frd_mem[2+WBLSB +: 4] } != f_addr_reg)
864					|| (rdaddr == lastaddr));
865			end
866	
867			if (f_mem_used[fc_addr])
868			begin
869				`ASSERT((fc_mem[1+2+WBLSB +: 3] == 3'h7)
870					== (f_pc && fc_addr == lastaddr));
871				`ASSERT(({ fifo_gie, fc_mem[2+WBLSB +: 4] } != f_addr_reg)
872					|| fc_addr == lastaddr);
873			end
874		end
875	
876		always @(*)
877		if (fifo_fill > 0)
878			assert({ fifo_gie, fifo_mem[lastaddr][2+WBLSB +: 4] } == f_last_reg);
879	
880		initial	assert(!fifo_full);
881		// }}}
882		////////////////////////////////////////////////////////////////////////
883		//
884		// Cover properties
885		// {{{
886		////////////////////////////////////////////////////////////////////////
887		//
888		//
889		always @(posedge i_clk)
890			cover(cyc && !fifo_full);
891	
892		always @(posedge i_clk)
893			cover((f_cyc)&&(f_stb)&&(!i_wb_stall)&&(!i_wb_ack)
894				&&(!o_pipe_stalled));
895	
896		always @(posedge i_clk)
897		if ((f_past_valid)&&(!$past(f_stb))&&($past(f_cyc)))
898			cover((f_cyc)&&(i_wb_ack));
899	
900		always @(posedge i_clk)
901		if ((f_past_valid)&&(!$past(f_stb))&&($past(f_cyc)))
902			cover($past(i_wb_ack)&&(i_wb_ack));
903	
904		always @(posedge i_clk)
905		if ((f_past_valid)&&($past(o_valid)))
906			cover(o_valid);
907	
908	`endif // FIFOCHECK
909		// }}}
910		always @(posedge i_clk)
911		if ((f_past_valid)&&($past(f_past_valid))&&($past(f_cyc))&&($past(f_cyc,2)))
912			`ASSERT($stable(o_wreg[4]));
913	
914		always @(*)
915			`ASSERT((!f_cyc)||(!o_valid)||(o_wreg[3:1]!=3'h7));
916	
917		// Make Verilator happy
918		// {{{
919		// Verilator lint_off UNUSED
920		wire	unused;
921		assign	unused = &{ 1'b0, f_nreqs, f_nacks };
922		// Verilator lint_off UNUSED
923		// }}}
924	`endif // FORMAL
925	// }}}
926	endmodule
927	//
928	//
929	// Usage (from yosys): (Before)	(A,!OPTZ)	(A,OPTZ)
930	//	Cells:		302	314		391
931	//	  FDRE		138	140		140
932	//	  LUT1		  2	  2		  2
933	//	  LUT2		 38	 41		 61
934	//	  LUT3		 13	 16		 33
935	//	  LUT4		  3	  8		 12
936	//	  LUT5		 22	 10		  8
937	//	  LUT6		 52	 59		 81
938	//	  MUXCY		  6	  6		  6
939	//	  MUXF7		 10	 13		 21
940	//	  MUXF8		  1	  2		 10
941	//	  RAM64X1D	  9	  9		  9
942	//	  XORCY		  8	  8		  8
943	//
944	//
945

