1	////////////////////////////////////////////////////////////////////////////////
2	//
3	// Filename:	rtl/core/memops.v
4	// {{{
5	// Project:	Zip CPU -- a small, lightweight, RISC CPU soft core
6	//
7	// Purpose:	A memory unit to support a CPU.
8	//
9	//	In the interests of code simplicity, this memory operator is
10	//	susceptible to unknown results should a new command be sent to it
11	//	before it completes the last one.  Unpredictable results might then
12	//	occurr.
13	//
14	//	BIG ENDIAN
15	//		Note that this core assumes a big endian bus, with the MSB
16	//		of the bus word being the least bus address
17	//
18	// Creator:	Dan Gisselquist, Ph.D.
19	//		Gisselquist Technology, LLC
20	//
21	////////////////////////////////////////////////////////////////////////////////
22	// }}}
23	// Copyright (C) 2015-2025, Gisselquist Technology, LLC
24	// {{{
25	// This program is free software (firmware): you can redistribute it and/or
26	// modify it under the terms of the GNU General Public License as published
27	// by the Free Software Foundation, either version 3 of the License, or (at
28	// your option) any later version.
29	//
30	// This program is distributed in the hope that it will be useful, but WITHOUT
31	// ANY WARRANTY; without even the implied warranty of MERCHANTIBILITY or
32	// FITNESS FOR A PARTICULAR PURPOSE.  See the GNU General Public License
33	// for more details.
34	//
35	// You should have received a copy of the GNU General Public License along
36	// with this program.  (It's in the $(ROOT)/doc directory.  Run make with no
37	// target there if the PDF file isn't present.)  If not, see
38	// <http://www.gnu.org/licenses/> for a copy.
39	// }}}
40	// License:	GPL, v3, as defined and found on www.gnu.org,
41	// {{{
42	//		http://www.gnu.org/licenses/gpl.html
43	//
44	////////////////////////////////////////////////////////////////////////////////
45	//
46	`default_nettype	none
47	// }}}
48	module	memops #(
49			// {{{
50			parameter	ADDRESS_WIDTH=28,
51			parameter	DATA_WIDTH=32,	// CPU's register width
52			parameter	BUS_WIDTH=32,
53			parameter [0:0]	OPT_LOCK=1'b1,
54					WITH_LOCAL_BUS=1'b1,
55					OPT_ALIGNMENT_ERR=1'b1,
56					OPT_LOWPOWER=1'b0,
57					OPT_LITTLE_ENDIAN = 1'b0,
58			localparam	AW=ADDRESS_WIDTH
59	`ifdef	FORMAL
60			, parameter	F_LGDEPTH = 2
61	`endif
62			// }}}
63		) (
64			// {{{
65			input	wire			i_clk, i_reset,
66			// CPU interface
67			// {{{
68			input	wire			i_stb, i_lock,
69			input	wire	[2:0]		i_op,
70			input	wire	[31:0]		i_addr,
71			input	wire [DATA_WIDTH-1:0]	i_data,
72			input	wire	[4:0]		i_oreg,
73			// CPU outputs
74			output	wire			o_busy,
75			output	reg			o_rdbusy,
76			output	reg			o_valid,
77			output	reg			o_err,
78			output	reg	[4:0]		o_wreg,
79			output	reg [DATA_WIDTH-1:0]	o_result,
80			// }}}
81			// Wishbone
82			// {{{
83			output	wire			o_wb_cyc_gbl,
84			output	wire			o_wb_cyc_lcl,
85			output	reg			o_wb_stb_gbl,
86			output	reg			o_wb_stb_lcl,
87			output	reg			o_wb_we,
88			output	reg	[AW-1:0]	o_wb_addr,
89			output	reg	[BUS_WIDTH-1:0]	o_wb_data,
90			output	reg [BUS_WIDTH/8-1:0]	o_wb_sel,
91			// Wishbone inputs
92			input	wire			i_wb_stall, i_wb_ack, i_wb_err,
93			input	wire	[BUS_WIDTH-1:0]	i_wb_data
94			// }}}
95			// }}}
96		);
97	
98		// Declarations
99		// {{{
100		localparam	WBLSB = $clog2(BUS_WIDTH/8);
101	`ifdef	FORMAL
102		wire	[(F_LGDEPTH-1):0]	f_nreqs, f_nacks, f_outstanding;
103	`endif
104	
105		wire		misaligned;
106		reg		r_wb_cyc_gbl, r_wb_cyc_lcl;
107		reg	[2+WBLSB-1:0]	r_op;
108		wire		lock_gbl, lock_lcl;
109		wire		lcl_bus, gbl_stb, lcl_stb;
110	
111		reg	[BUS_WIDTH/8-1:0]	oword_sel;
112		wire	[BUS_WIDTH/8-1:0]	pre_sel;
113		wire	[BUS_WIDTH-1:0]		pre_result;
114	
115		wire	[1:0]		oshift2;
116		wire	[WBLSB-1:0]	oshift;
117	
118		// }}}
119	
120		// misaligned
121		// {{{
122		generate if (OPT_ALIGNMENT_ERR)
123		begin : GENERATE_ALIGNMENT_ERR
124			reg	r_misaligned;
125	
126			always @(*)
127			casez({ i_op[2:1], i_addr[1:0] })
128			4'b01?1: r_misaligned = i_stb; // Words must be halfword aligned
129			4'b0110: r_misaligned = i_stb; // Words must be word aligned
130			4'b10?1: r_misaligned = i_stb; // Halfwords must be aligned
131			// 4'b11??: r_misaligned <= 1'b0; Byte access are never misaligned
132			default: r_misaligned = 1'b0;
133			endcase
134	
135			assign	misaligned = r_misaligned;
136		end else begin : NO_MISALIGNMENT_ERR
137			assign	misaligned = 1'b0;
138		end endgenerate
139		// }}}
140	
141		// lcl_stb, gbl_stb
142		// {{{
143		assign	lcl_bus = (WITH_LOCAL_BUS)&&(i_addr[31:24]==8'hff);
144		assign	lcl_stb = (i_stb)&&( lcl_bus)&&(!misaligned);
145		assign	gbl_stb = (i_stb)&&(!lcl_bus)&&(!misaligned);
146		// }}}
147	
148		// r_wb_cyc_gbl, r_wb_cyc_lcl
149		// {{{
150		initial	r_wb_cyc_gbl = 1'b0;
151		initial	r_wb_cyc_lcl = 1'b0;
152		always @(posedge i_clk)
153		if (i_reset)
154		begin
155			r_wb_cyc_gbl <= 1'b0;
156			r_wb_cyc_lcl <= 1'b0;
157		end else if ((r_wb_cyc_gbl)||(r_wb_cyc_lcl))
158		begin
159			if ((i_wb_ack)||(i_wb_err))
160			begin
161				r_wb_cyc_gbl <= 1'b0;
162				r_wb_cyc_lcl <= 1'b0;
163			end
164		end else begin // New memory operation
165			// Grab the wishbone
166			r_wb_cyc_lcl <= (lcl_stb);
167			r_wb_cyc_gbl <= (gbl_stb);
168		end
169		// }}}
170	
171		// o_wb_stb_gbl
172		// {{{
173		initial	o_wb_stb_gbl = 1'b0;
174		always @(posedge i_clk)
175		if (i_reset)
176			o_wb_stb_gbl <= 1'b0;
177		else if ((i_wb_err)&&(r_wb_cyc_gbl))
178			o_wb_stb_gbl <= 1'b0;
179		else if (gbl_stb)
180			o_wb_stb_gbl <= 1'b1;
181		else if (o_wb_cyc_gbl)
182			o_wb_stb_gbl <= (o_wb_stb_gbl)&&(i_wb_stall);
183		//  }}}
184	
185		// o_wb_stb_lcl
186		// {{{
187		initial	o_wb_stb_lcl = 1'b0;
188		always @(posedge i_clk)
189		if (i_reset)
190			o_wb_stb_lcl <= 1'b0;
191		else if ((i_wb_err)&&(r_wb_cyc_lcl))
192			o_wb_stb_lcl <= 1'b0;
193		else if (lcl_stb)
194			o_wb_stb_lcl <= 1'b1;
195		else if (o_wb_cyc_lcl)
196			o_wb_stb_lcl <= (o_wb_stb_lcl)&&(i_wb_stall);
197		// }}}
198	
199		// o_wb_we, o_wb_data, o_wb_sel
200		// {{{
201		always @(*)
202		begin
203			oword_sel = 0;
204	
205			casez({ OPT_LITTLE_ENDIAN, i_op[2:1], i_addr[1:0] })
206			5'b00???: oword_sel[3:0] = 4'b1111;
207			5'b0100?: oword_sel[3:0] = 4'b1100;
208			5'b0101?: oword_sel[3:0] = 4'b0011;
209			5'b01100: oword_sel[3:0] = 4'b1000;
210			5'b01101: oword_sel[3:0] = 4'b0100;
211			5'b01110: oword_sel[3:0] = 4'b0010;
212			5'b01111: oword_sel[3:0] = 4'b0001;
213			//
214			// verilator coverage_off
215			5'b10???: oword_sel[3:0] = 4'b1111;
216			5'b1100?: oword_sel[3:0] = 4'b0011;
217			5'b1101?: oword_sel[3:0] = 4'b1100;
218			5'b11100: oword_sel[3:0] = 4'b0001;
219			5'b11101: oword_sel[3:0] = 4'b0010;
220			5'b11110: oword_sel[3:0] = 4'b0100;
221			5'b11111: oword_sel[3:0] = 4'b1000;
222			// verilator coverage_on
223			//
224			default: oword_sel[3:0] = 4'b1111;
225			endcase
226		end
227	
228		// pre_sel
229		// {{{
230		generate if (BUS_WIDTH == 32)
231		begin : COPY_PRESEL
232			assign	pre_sel = oword_sel;
233		end else if (OPT_LITTLE_ENDIAN)
234		begin : GEN_LILPRESEL
235			wire	[WBLSB-3:0]	shift;
236	
237			assign	shift = i_addr[WBLSB-1:2];
238			assign	pre_sel = oword_sel << (4 * i_addr[WBLSB-1:2]);
239		end else begin : GEN_PRESEL
240			wire	[WBLSB-3:0]	shift;
241	
242			assign	shift = {(WBLSB-2){1'b1}} ^ i_addr[WBLSB-1:2];
243			assign	pre_sel = oword_sel << (4 * shift);
244		end endgenerate
245		// }}}
246	
247		assign	oshift  = i_addr[WBLSB-1:0];
248		assign	oshift2 = i_addr[1:0];
249	
250		initial	o_wb_we   = 1'b0;
251		initial	o_wb_data = 0;
252		initial	o_wb_sel  = 0;
253		always @(posedge i_clk)
254		if (i_stb)
255		begin
256			o_wb_we   <= i_op[0];
257			if (OPT_LOWPOWER)
258			begin
259				if (lcl_bus)
260				begin
261					// {{{
262					o_wb_data <= 0;
263					casez({ OPT_LITTLE_ENDIAN, i_op[2:1] })
264					3'b010: o_wb_data[31:0] <= { i_data[15:0], {(16){1'b0}} } >> (8*oshift2);
265					3'b011: o_wb_data[31:0] <= { i_data[ 7:0], {(24){1'b0}} } >> (8*oshift2);
266					3'b00?: o_wb_data[31:0] <= i_data[31:0];
267					//
268					// verilator coverage_off
269					3'b110: o_wb_data <= { {(BUS_WIDTH-16){1'b0}}, i_data[15:0] } << (8*oshift2);
270					3'b111: o_wb_data <= { {(BUS_WIDTH-8){1'b0}},  i_data[ 7:0] } << (8*oshift2);
271					3'b10?: o_wb_data <= { {(BUS_WIDTH-32){1'b0}}, i_data[31:0] } << (8*oshift2);
272					// verilator coverage_on
273					//
274					endcase
275					// }}}
276				end else begin
277					// {{{
278					casez({ OPT_LITTLE_ENDIAN, i_op[2:1] })
279					3'b010: o_wb_data <= { i_data[15:0], {(BUS_WIDTH-16){1'b0}} } >> (8*oshift);
280					3'b011: o_wb_data <= { i_data[ 7:0], {(BUS_WIDTH- 8){1'b0}} } >> (8*oshift);
281					3'b00?: o_wb_data <= { i_data[31:0], {(BUS_WIDTH-32){1'b0}} } >> (8*oshift);
282					//
283					3'b110: o_wb_data <= { {(BUS_WIDTH-16){1'b0}}, i_data[15:0] } << (8*oshift);
284					3'b111: o_wb_data <= { {(BUS_WIDTH-8){1'b0}},  i_data[ 7:0] } << (8*oshift);
285					3'b10?: o_wb_data <= { {(BUS_WIDTH-32){1'b0}}, i_data[31:0] } << (8*oshift);
286					//
287					endcase
288					// }}}
289				end
290			end else
291				casez({ i_op[2:1] })
292				2'b10: o_wb_data <= { (BUS_WIDTH/16){ i_data[15:0] } };
293				2'b11: o_wb_data <= { (BUS_WIDTH/ 8){ i_data[7:0] } };
294				default: o_wb_data <= {(BUS_WIDTH/32){i_data}};
295				endcase
296	
297			if (lcl_bus)
298			begin
299				o_wb_addr <= i_addr[2 +: (AW+2>32 ? (32-2) : AW)];
300				o_wb_sel <= oword_sel;
301			end else begin
302				o_wb_addr <= i_addr[WBLSB +: (AW+WBLSB>32 ? (32-WBLSB) : AW)];
303				o_wb_sel <= pre_sel;
304			end
305	
306			r_op <= { i_op[2:1] , i_addr[WBLSB-1:0] };
307		end else if ((OPT_LOWPOWER)&&(!o_wb_cyc_gbl)&&(!o_wb_cyc_lcl))
308		begin
309			o_wb_we   <= 1'b0;
310			o_wb_addr <= 0;
311			o_wb_data <= {(BUS_WIDTH){1'b0}};
312			o_wb_sel  <= {(BUS_WIDTH/8){1'b0}};
313		end
314		// }}}
315	
316		// o_valid
317		// {{{
318		initial	o_valid = 1'b0;
319		always @(posedge i_clk)
320		if (i_reset)
321			o_valid <= 1'b0;
322		else
323			o_valid <= (((o_wb_cyc_gbl)||(o_wb_cyc_lcl))
324					&&(i_wb_ack)&&(!o_wb_we));
325		// }}}
326	
327		// o_err
328		// {{{
329		initial	o_err = 1'b0;
330		always @(posedge i_clk)
331		if (i_reset)
332			o_err <= 1'b0;
333		else if ((r_wb_cyc_gbl)||(r_wb_cyc_lcl))
334			o_err <= i_wb_err;
335		else if ((i_stb)&&(!o_busy))
336			o_err <= misaligned;
337		else
338			o_err <= 1'b0;
339		// }}}
340	
341		assign	o_busy = (r_wb_cyc_gbl)||(r_wb_cyc_lcl);
342	
343		// o_rdbusy
344		// {{{
345		initial	o_rdbusy = 1'b0;
346		always @(posedge i_clk)
347		if (i_reset|| ((o_wb_cyc_gbl || o_wb_cyc_lcl)&&(i_wb_err || i_wb_ack)))
348			o_rdbusy <= 1'b0;
349		else if (i_stb && !i_op[0] && !misaligned)
350			o_rdbusy <= 1'b1;
351		else if (o_valid)
352			o_rdbusy <= 1'b0;
353		// }}}
354	
355		always @(posedge i_clk)
356		if (i_stb)
357			o_wreg    <= i_oreg;
358	
359		// o_result
360		// {{{
361		generate if (OPT_LITTLE_ENDIAN)
362		begin : LILEND_RESULT
363	
364			assign	pre_result = i_wb_data >> (8*r_op[$clog2(BUS_WIDTH/8)-1:0]);
365	
366		end else begin : BIGEND_RESULT
367	
368			assign	pre_result = i_wb_data << (8*r_op[$clog2(BUS_WIDTH/8)-1:0]);
369	
370		end endgenerate
371	
372		always @(posedge i_clk)
373		if ((OPT_LOWPOWER)&&(!i_wb_ack))
374			o_result <= 32'h0;
375		else if (o_wb_cyc_lcl && (BUS_WIDTH != 32))
376		begin
377			// The Local bus is naturally (and only) a 32-bit bus
378			casez({ OPT_LITTLE_ENDIAN, r_op[WBLSB +: 2], r_op[1:0] })
379			5'b?01??: o_result <= i_wb_data[31:0];
380			//
381			// Big endian
382			5'b0100?: o_result <= { 16'h00, i_wb_data[31:16] };
383			5'b0101?: o_result <= { 16'h00, i_wb_data[15: 0] };
384			5'b01100: o_result <= { 24'h00, i_wb_data[31:24] };
385			5'b01101: o_result <= { 24'h00, i_wb_data[23:16] };
386			5'b01110: o_result <= { 24'h00, i_wb_data[15: 8] };
387			5'b01111: o_result <= { 24'h00, i_wb_data[ 7: 0] };
388			//
389			// Little endian : Same bus result, just grab a different bits
390			//   from the bus return to send back to the CPU.
391			// verilator coverage_off
392			5'b1100?: o_result <= { 16'h00, i_wb_data[15: 0] };
393			5'b1101?: o_result <= { 16'h00, i_wb_data[31:16] };
394			5'b11100: o_result <= { 24'h00, i_wb_data[ 7: 0] };
395			5'b11101: o_result <= { 24'h00, i_wb_data[15: 8] };
396			5'b11110: o_result <= { 24'h00, i_wb_data[23:16] };
397			5'b11111: o_result <= { 24'h00, i_wb_data[31:24] };
398			// verilator coverage_on
399			default: o_result <= i_wb_data[31:0];
400			endcase
401		end else begin
402			casez({ OPT_LITTLE_ENDIAN, r_op[$clog2(BUS_WIDTH/8) +: 2] })
403			// Word
404			//
405			// Big endian
406			3'b00?: o_result <= pre_result[BUS_WIDTH-1:BUS_WIDTH-32];
407			3'b010: o_result <= { 16'h00, pre_result[BUS_WIDTH-1:BUS_WIDTH-16] };
408			3'b011: o_result <= { 24'h00, pre_result[BUS_WIDTH-1:BUS_WIDTH-8] };
409			//
410			// Little endian : Same bus result, just grab a different bits
411			//   from the bus return to send back to the CPU.
412			// verilator coverage_off
413			3'b10?: o_result <= pre_result[31: 0];
414			3'b110: o_result <= { 16'h00, pre_result[15: 0] };
415			3'b111: o_result <= { 24'h00, pre_result[ 7: 0] };
416			// verilator coverage_on
417			//
418			// Just to have an (unused) default
419			// default: o_result <= pre_result[31:0]; (Messes w/ coverage)
420			endcase
421		end
422		// }}}
423	
424		// lock_gbl and lock_lcl
425		// {{{
426		generate
427		if (OPT_LOCK)
428		begin : GEN_LOCK
429			// {{{
430			reg	r_lock_gbl, r_lock_lcl;
431	
432			initial	r_lock_gbl = 1'b0;
433			initial	r_lock_lcl = 1'b0;
434	
435			always @(posedge i_clk)
436			if (i_reset)
437			begin
438				r_lock_gbl <= 1'b0;
439				r_lock_lcl <= 1'b0;
440			end else if (((i_wb_err)&&((r_wb_cyc_gbl)||(r_wb_cyc_lcl)))
441					||(misaligned))
442			begin
443				// Kill the lock if
444				//	there's a bus error, or
445				//	User requests a misaligned memory op
446				r_lock_gbl <= 1'b0;
447				r_lock_lcl <= 1'b0;
448			end else begin
449				// Kill the lock if
450				//	i_lock goes down
451				//	User starts on the global bus, then switches
452				//	  to local or vice versa
453				r_lock_gbl <= (i_lock)&&((r_wb_cyc_gbl)||(lock_gbl))
454						&&(!lcl_stb);
455				r_lock_lcl <= (i_lock)&&((r_wb_cyc_lcl)||(lock_lcl))
456						&&(!gbl_stb);
457			end
458	
459			assign	lock_gbl = r_lock_gbl;
460			assign	lock_lcl = r_lock_lcl;
461	
462			assign	o_wb_cyc_gbl = (r_wb_cyc_gbl)||(lock_gbl);
463			assign	o_wb_cyc_lcl = (r_wb_cyc_lcl)||(lock_lcl);
464			// }}}
465		end else begin : NO_LOCK
466			// {{{
467			assign	o_wb_cyc_gbl = (r_wb_cyc_gbl);
468			assign	o_wb_cyc_lcl = (r_wb_cyc_lcl);
469	
470			assign	{ lock_gbl, lock_lcl } = 2'b00;
471	
472			// Make verilator happy
473			// verilator lint_off UNUSED
474			wire	[2:0]	lock_unused;
475			assign	lock_unused = { i_lock, lock_gbl, lock_lcl };
476			// verilator lint_on  UNUSED
477			// }}}
478		end endgenerate
479		// }}}
480	
481	`ifdef	VERILATOR
482		always @(posedge i_clk)
483		if ((r_wb_cyc_gbl)||(r_wb_cyc_lcl))
484			assert(!i_stb);
485	`endif
486	
487	
488		// Make verilator happy
489		// {{{
490		// verilator coverage_off
491		// verilator lint_off UNUSED
492		wire	unused;
493		assign	unused = &{ 1'b0, pre_result };
494		generate if (AW < 22)
495		begin : TOO_MANY_ADDRESS_BITS
496	
497			wire	[(21-AW):0] unused_addr;
498			assign	unused_addr = i_addr[23:(AW+2)];
499	
500		end endgenerate
501		// verilator lint_on  UNUSED
502		// verilator coverage_on
503		// }}}
504	////////////////////////////////////////////////////////////////////////////////
505	////////////////////////////////////////////////////////////////////////////////
506	////////////////////////////////////////////////////////////////////////////////
507	//
508	// Formal properties
509	// {{{
510	////////////////////////////////////////////////////////////////////////////////
511	////////////////////////////////////////////////////////////////////////////////
512	////////////////////////////////////////////////////////////////////////////////
513	`ifdef	FORMAL
514	`define	ASSERT	assert
515	`ifdef	MEMOPS
516	`define	ASSUME	assume
517	`else
518	`define	ASSUME	assert
519	`endif
520		reg	f_past_valid;
521	
522		reg	[2:0]		fcpu_op;
523		reg	[31:0]		fcpu_addr, fcpu_data;;
524		reg	[BUS_WIDTH-1:0]	fbus_data, fpre_data;
525		reg [$clog2(BUS_WIDTH/8)-1:0] fcpu_shift;
526		reg			fcpu_local, fcpu_misaligned;
527		reg	[BUS_WIDTH/8-1:0]	fbus_sel, fpre_sel;
528	
529		initial	f_past_valid = 0;
530		always @(posedge i_clk)
531			f_past_valid <= 1'b1;
532	
533		always @(*)
534		if (!f_past_valid)
535			`ASSUME(i_reset);
536	
537		////////////////////////////////////////////////////////////////////////
538		//
539		// Bus properties
540		// {{{
541		////////////////////////////////////////////////////////////////////////
542		//
543		//
544		initial	`ASSUME(!i_stb);
545	
546		wire	f_cyc, f_stb;
547		assign	f_cyc = (o_wb_cyc_gbl)||(o_wb_cyc_lcl);
548		assign	f_stb = (o_wb_stb_gbl)||(o_wb_stb_lcl);
549	
550		fwb_master #(
551			// {{{
552			.AW(AW), .F_LGDEPTH(F_LGDEPTH), .DW(BUS_WIDTH),
553			.F_OPT_RMW_BUS_OPTION(OPT_LOCK),
554			.F_OPT_DISCONTINUOUS(OPT_LOCK)
555			// }}}
556		) f_wb(
557			// {{{
558			i_clk, i_reset,
559			f_cyc, f_stb, o_wb_we, o_wb_addr, o_wb_data, o_wb_sel,
560			i_wb_ack, i_wb_stall, i_wb_data, i_wb_err,
561			f_nreqs, f_nacks, f_outstanding
562			// }}}
563		);
564	
565	
566		// Rule: Only one of the two CYC's may be valid, never both
567		always @(posedge i_clk)
568			`ASSERT((!o_wb_cyc_gbl)||(!o_wb_cyc_lcl));
569	
570		// Rule: Only one of the two STB's may be valid, never both
571		always @(posedge i_clk)
572			`ASSERT((!o_wb_stb_gbl)||(!o_wb_stb_lcl));
573	
574		// Rule: if WITH_LOCAL_BUS is ever false, neither the local STB nor CYC
575		// may be valid
576		always @(*)
577		if (!WITH_LOCAL_BUS)
578		begin
579			`ASSERT(!o_wb_cyc_lcl);
580			`ASSERT(!o_wb_stb_lcl);
581		end
582	
583		// Rule: If the global CYC is ever true, the LCL one cannot be true
584		// on the next clock without an intervening idle of both
585		always @(posedge i_clk)
586		if ((f_past_valid)&&($past(r_wb_cyc_gbl)))
587			`ASSERT(!r_wb_cyc_lcl);
588	
589		// Same for if the LCL CYC is true
590		always @(posedge i_clk)
591		if ((f_past_valid)&&($past(r_wb_cyc_lcl)))
592			`ASSERT(!r_wb_cyc_gbl);
593	
594		// STB can never be true unless CYC is also true
595		always @(posedge i_clk)
596		if (o_wb_stb_gbl)
597			`ASSERT(r_wb_cyc_gbl);
598	
599		always @(posedge i_clk)
600		if (o_wb_stb_lcl)
601			`ASSERT(r_wb_cyc_lcl);
602	
603		// This core only ever has zero or one outstanding transaction(s)
604		always @(posedge i_clk)
605		if ((o_wb_stb_gbl)||(o_wb_stb_lcl))
606		begin
607			`ASSERT(f_outstanding == 0);
608		end else
609			`ASSERT((f_outstanding == 0)||(f_outstanding == 1));
610	
611		// The LOCK function only allows up to two transactions (at most)
612		// before CYC must be dropped.
613		always @(posedge i_clk)
614		if ((o_wb_stb_gbl)||(o_wb_stb_lcl))
615		begin
616			if (OPT_LOCK)
617			begin
618				`ASSERT((f_outstanding == 0)||(f_outstanding == 1));
619			end else
620				`ASSERT(f_nreqs <= 1);
621		end
622		// }}}
623		////////////////////////////////////////////////////////////////////////
624		//
625		// CPU properties
626		// {{{
627		////////////////////////////////////////////////////////////////////////
628		//
629		//
630		reg				f_done;
631		wire	[(F_LGDEPTH-1):0]	cpu_outstanding;
632		wire				f_pc, f_rdbusy, f_gie, f_read_cycle;
633		wire	[4:0]			f_last_reg;
634		wire	[4:0]			f_addr_reg;
635		// Verilator lint_off UNDRIVEN
636		(* anyseq *)	reg	[4:0]	f_areg;
637		// Verilator lint_on  UNDRIVEN
638	
639		assign	f_rdbusy = f_cyc && (f_stb || f_outstanding > 0) && !o_wb_we;
640	
641		initial	f_done = 1'b0;
642		always @(posedge i_clk)
643		if (i_reset)
644			f_done <= 1'b0;
645		else
646			f_done <= ((o_wb_cyc_gbl)||(o_wb_cyc_lcl))&&(i_wb_ack);
647	
648		fmem #(
649			// {{{
650			.F_LGDEPTH(F_LGDEPTH),
651			.OPT_LOCK(OPT_LOCK),
652			.OPT_MAXDEPTH(1)
653			// }}}
654		) fmemi(
655			// {{{
656			.i_clk(i_clk),
657			.i_sys_reset(i_reset),
658			.i_cpu_reset(i_reset),
659			.i_stb(i_stb),
660			.i_pipe_stalled(o_busy),
661			.i_clear_cache(1'b0),
662			.i_lock(i_lock),
663			.i_op(i_op), .i_addr(i_addr), .i_data(i_data), .i_oreg(i_oreg),
664			.i_areg(f_areg),
665			.i_busy(o_busy),
666			.i_rdbusy(f_rdbusy),
667			.i_valid(o_valid), .i_done(f_done), .i_err(o_err),
668			.i_wreg(o_wreg), .i_result(o_result),
669			.f_outstanding(cpu_outstanding),
670			.f_pc(f_pc),
671			.f_gie(f_gie),
672			.f_read_cycle(f_read_cycle),
673			.f_last_reg(f_last_reg), .f_addr_reg(f_addr_reg)
674			// }}}
675		);
676	
677		always @(*)
678		if (!o_err)
679			assert(cpu_outstanding == f_outstanding + (f_stb ? 1:0)
680						+ ((f_done || o_err) ? 1:0));
681	
682		always @(*)
683			assert(cpu_outstanding <= 1);
684	
685		always @(*)
686		if (f_pc)
687		begin
688			assert(o_wreg[3:1] == 3'h7);
689		end else if (f_rdbusy)
690			assert(o_wreg[3:1] != 3'h7);
691	
692		always @(*)
693		if (o_busy)
694			assert(o_wreg[4] == f_gie);
695	
696		always @(*)
697		if (!o_err)
698			assert(f_rdbusy == o_rdbusy);
699	
700		always @(*)
701		if (o_busy)
702			assert(o_wb_we == !f_read_cycle);
703	
704		always @(*)
705		if (cpu_outstanding > 0)
706			assert(f_last_reg == o_wreg);
707		// }}}
708		////////////////////////////////////////////////////////////////////////
709		//
710		// Tying the two together
711		// {{{
712		////////////////////////////////////////////////////////////////////////
713		//
714		//
715	
716		// Following any i_stb request, assuming we are idle, immediately
717		// begin a bus transaction
718		always @(posedge i_clk)
719		if ((f_past_valid)&&($past(i_stb))
720			&&(!$past(f_cyc))&&(!$past(i_reset)))
721		begin
722			if ($past(misaligned))
723			begin
724				`ASSERT(!f_cyc);
725				`ASSERT(!o_busy);
726				`ASSERT(o_err);
727				`ASSERT(!o_valid);
728			end else begin
729				`ASSERT(f_cyc);
730				`ASSERT(o_busy);
731			end
732		end
733	
734	//	always @(posedge i_clk)
735	//	if (o_busy)
736	//		`ASSUME(!i_stb);
737	
738		always @(*)
739		if (o_err || o_valid)
740			`ASSERT(!o_busy);
741	
742		always @(posedge i_clk)
743		if (o_wb_cyc_gbl)
744			`ASSERT((o_busy)||(lock_gbl));
745	
746		always @(posedge i_clk)
747		if (o_wb_cyc_lcl)
748			`ASSERT((o_busy)||(lock_lcl));
749	
750		always @(posedge i_clk)
751		if (f_outstanding > 0)
752			`ASSERT(o_busy);
753	
754		// If a transaction ends in an error, send o_err on the output port.
755		always @(posedge i_clk)
756		if (f_past_valid && !$past(i_reset))
757		begin
758			if (($past(f_cyc))&&($past(i_wb_err)))
759			begin
760				`ASSERT(o_err);
761			end else if ($past(misaligned))
762				`ASSERT(o_err);
763		end
764	
765		// Always following a successful ACK, return an O_VALID value.
766		always @(posedge i_clk)
767		if (f_past_valid && !$past(i_reset))
768		begin
769			if(($past(f_cyc))&&($past(i_wb_ack))
770					&&(!$past(o_wb_we)))
771			begin
772				`ASSERT(o_valid);
773			end else if ($past(misaligned))
774			begin
775				`ASSERT((!o_valid)&&(o_err));
776			end else
777				`ASSERT(!o_valid);
778		end
779	
780		always @(posedge i_clk)
781		if (i_stb)
782		begin
783			fcpu_op   <= i_op;
784			fcpu_addr <= i_addr;
785			fcpu_data <= i_data;
786		end
787	
788		always @(*)
789		begin
790			fcpu_local = (&fcpu_addr[31:24]) && WITH_LOCAL_BUS;
791	
792			if (OPT_LITTLE_ENDIAN)
793			begin
794				// {{{
795				casez(fcpu_op[2:1])
796				2'b11: fpre_sel = { {(BUS_WIDTH/8-1){1'b0}}, 1'b1 };
797				2'b10: fpre_sel = { {(BUS_WIDTH/8-2){1'b0}}, 2'b11 };
798				2'b0?: fpre_sel = { {(BUS_WIDTH/8-4){1'b0}}, 4'b1111 };
799				endcase
800	
801				casez(fcpu_op[2:1])
802				2'b11: fpre_data = { {(BUS_WIDTH- 8){1'b0}}, fcpu_data[ 7:0] };
803				2'b10: fpre_data = { {(BUS_WIDTH-16){1'b0}}, fcpu_data[15:0] };
804				2'b0?: fpre_data = { {(BUS_WIDTH-32){1'b0}}, fcpu_data[31:0] };
805				endcase
806				// }}}
807			end else if (fcpu_local)
808			begin
809				// {{{
810				fpre_sel = 0;
811				casez(fcpu_op[2:1])
812				2'b11: fpre_sel[3:0] = 4'b1000;
813				2'b10: fpre_sel[3:0] = 4'b1100;
814				2'b0?: fpre_sel[3:0] = 4'b1111;
815				endcase
816	
817				fpre_data = 0;
818				casez(fcpu_op[2:1])
819				2'b11: fpre_data[31:0] = { fcpu_data[ 7:0], {(24){1'b0}} };
820				2'b10: fpre_data[31:0] = { fcpu_data[15:0], {(16){1'b0}} };
821				2'b0?: fpre_data[31:0] = fcpu_data[31:0];
822				endcase
823				// }}}
824			end else begin
825				// {{{
826				casez(fcpu_op[2:1])
827				2'b11: fpre_sel = { 1'b1,    {(BUS_WIDTH/8-1){1'b0}} };
828				2'b10: fpre_sel = { 2'b11,   {(BUS_WIDTH/8-2){1'b0}} };
829				2'b0?: fpre_sel = { 4'b1111, {(BUS_WIDTH/8-4){1'b0}} };
830				endcase
831	
832				casez(fcpu_op[2:1])
833				2'b11: fpre_data = { fcpu_data[ 7:0], {(BUS_WIDTH- 8){1'b0}} };
834				2'b10: fpre_data = { fcpu_data[15:0], {(BUS_WIDTH-16){1'b0}} };
835				2'b0?: fpre_data = { fcpu_data[31:0], {(BUS_WIDTH-32){1'b0}} };
836				endcase
837				// }}}
838			end
839	
840	
841			casez({ fcpu_op[2:1], fcpu_addr[1:0] })
842			4'b01?1: fcpu_misaligned = 1'b1; // Words must be halfword aligned
843			4'b0110: fcpu_misaligned = 1'b1; // Words must be word aligned
844			4'b10?1: fcpu_misaligned = 1'b1; // Halfwords must be aligned
845			// 4'b11??: fcpu_misaligned <= 1'b0; Byte access are never misaligned
846			default: fcpu_misaligned = 1'b0;
847			endcase
848	
849			if (fcpu_local)
850			begin
851				fcpu_shift = fcpu_addr[1:0];
852				if (OPT_LITTLE_ENDIAN)
853				begin
854					fbus_sel   = fpre_sel  << fcpu_shift;
855					fbus_data  = fpre_data << (8*fcpu_shift);
856				end else begin
857					fbus_sel   = fpre_sel  >> (fcpu_shift + (DATA_WIDTH/8-4));
858					fbus_data  = fpre_data >> (8*(fcpu_shift + (DATA_WIDTH/8-4)));
859				end
860			end else begin
861				fcpu_shift = fcpu_addr[WBLSB-1:0];
862				if (OPT_LITTLE_ENDIAN)
863				begin
864					fbus_sel  = fpre_sel  << fcpu_shift;
865					fbus_data = fpre_data << (8*fcpu_shift);
866				end else begin
867					fbus_sel  = fpre_sel  >> fcpu_shift;
868					fbus_data = fpre_data >> (8*fcpu_shift);
869				end
870			end
871	
872			if (!OPT_LOWPOWER)
873			casez(fcpu_op[2:1])
874			2'b11: fbus_data = {(BUS_WIDTH/ 8){fcpu_data[ 7:0] } };
875			2'b10: fbus_data = {(BUS_WIDTH/16){fcpu_data[15:0] } };
876			2'b0?: fbus_data = {(BUS_WIDTH/32){fcpu_data[31:0] } };
877			endcase
878		end
879	
880		always @(*)
881		if (OPT_ALIGNMENT_ERR && fcpu_misaligned)
882			assert(!o_valid && !f_cyc);
883	
884		always @(*)
885		if (f_stb)
886		begin
887			if (fcpu_local)
888			begin
889				assert(o_wb_stb_lcl);
890				assert(o_wb_addr == fcpu_addr[AW+1:2]);
891			end else begin
892				assert(o_wb_stb_gbl);
893				assert(o_wb_addr == fcpu_addr[WBLSB +: AW]);
894			end
895	
896			if (fcpu_op[0])
897			begin
898				`ASSERT(o_wb_we);
899				`ASSERT(fcpu_misaligned || o_wb_sel  == fbus_sel);
900				`ASSERT(fcpu_misaligned || o_wb_data == fbus_data);
901			end else begin
902				`ASSERT(!o_wb_we);
903			end
904		end
905	
906		always @(*)
907		if (f_cyc)
908			assert(o_wb_cyc_lcl == fcpu_local);
909	
910		initial	o_wb_we = 1'b0;
911		always @(posedge i_clk)
912		if ((f_past_valid)&&(!$past(i_reset))&&($past(i_stb)))
913		begin
914			// On a write, assert o_wb_we should be true
915			assert( $past(i_op[0]) == o_wb_we);
916		end
917	
918		always @(posedge i_clk)
919		if (o_wb_stb_lcl)
920			`ASSERT(fcpu_local);
921	
922		always @(posedge i_clk)
923		if ((f_past_valid)&&(!$past(i_reset))&&($past(misaligned)))
924		begin
925			`ASSERT(!o_wb_cyc_gbl);
926			`ASSERT(!o_wb_cyc_lcl);
927			`ASSERT(!o_wb_stb_gbl);
928			`ASSERT(!o_wb_stb_lcl);
929			`ASSERT(o_err);
930		end
931	
932	//	always @(posedge i_clk)
933	//	if ((!f_past_valid)||($past(i_reset)))
934	//		`ASSUME(!i_stb);
935	
936		always @(posedge i_clk)
937		if ((f_past_valid)&&(OPT_LOCK)
938				&&(!$past(i_reset))&&(!$past(i_wb_err))
939				&&(!$past(misaligned))
940				&&(!$past(lcl_stb))
941				&&($past(i_lock))&&($past(lock_gbl)))
942			assert(lock_gbl);
943	
944		always @(posedge i_clk)
945		if ((f_past_valid)&&(OPT_LOCK)
946				&&(!$past(i_reset))&&(!$past(i_wb_err))
947				&&(!$past(misaligned))
948				&&(!$past(lcl_stb))
949				&&($past(o_wb_cyc_gbl))&&($past(i_lock))
950				&&($past(lock_gbl)))
951			assert(o_wb_cyc_gbl);
952	
953		always @(posedge i_clk)
954		if ((f_past_valid)&&(OPT_LOCK)
955				&&(!$past(i_reset))&&(!$past(i_wb_err))
956				&&(!$past(misaligned))
957				&&(!$past(gbl_stb))
958				&&($past(o_wb_cyc_lcl))&&($past(i_lock))
959				&&($past(lock_lcl)))
960			assert(o_wb_cyc_lcl);
961		// }}}
962		////////////////////////////////////////////////////////////////////////
963		//
964		// Cover properties
965		// {{{
966		////////////////////////////////////////////////////////////////////////
967		//
968		//
969		always @(posedge i_clk)
970			cover(i_wb_ack);
971	
972		// Cover a response on the same clock it is made
973		always @(posedge i_clk)
974			cover((o_wb_stb_gbl)&&(i_wb_ack));
975	
976		// Cover a response a clock later
977		always @(posedge i_clk)
978			cover((o_wb_stb_gbl)&&(i_wb_ack));
979	
980		always @(posedge i_clk)
981			cover(f_done);
982	
983		always @(posedge i_clk)
984			cover(f_done && !o_busy);
985	
986		generate if (WITH_LOCAL_BUS)
987		begin
988	
989			// Same things on the local bus
990			always @(posedge i_clk)
991				cover((o_wb_cyc_lcl)&&(!o_wb_stb_lcl)&&(i_wb_ack));
992			always @(posedge i_clk)
993				cover((o_wb_stb_lcl)&&(i_wb_ack));
994	
995		end endgenerate
996		// }}}
997	
998		// Make Verilator happy
999		// {{{
1000		// Verilator lint_off UNUSED
1001		wire	unused;
1002		assign	unused = &{ 1'b0, f_nacks, f_addr_reg };
1003		// Verilator lint_on  UNUSED
1004		// }}}
1005	`endif
1006	// }}}
1007	endmodule
1008	//
1009	//
1010	// Usage (from yosys):
1011	//		(BFOR)	(!ZOI,ALIGN)	(ZOI,ALIGN)	(!ZOI,!ALIGN)
1012	//	Cells	 230		226		281		225
1013	//	  FDRE	 114		116		116		116
1014	//	  LUT2	  17		 23		 76		 19
1015	//	  LUT3	   9		 23		 17		 20
1016	//	  LUT4	  15		  4		 11		 14
1017	//	  LUT5	  18		 18		  7		 15
1018	//	  LUT6	  33		 18		 54		 38
1019	//	  MUX7	  16		 12		  		  2
1020	//	  MUX8	   8		  1				  1
1021	//
1022	//
1023

