////////////////////////////////////////////////////////////////////////////////
//
// Filename:	rtl/core/memops.v
// {{{
// Project:	Zip CPU -- a small, lightweight, RISC CPU soft core
//
// Purpose:	A memory unit to support a CPU.
//
//	In the interests of code simplicity, this memory operator is
//	susceptible to unknown results should a new command be sent to it
//	before it completes the last one.  Unpredictable results might then
//	occurr.
//
//	BIG ENDIAN
//		Note that this core assumes a big endian bus, with the MSB
//		of the bus word being the least bus address
//
// Creator:	Dan Gisselquist, Ph.D.
//		Gisselquist Technology, LLC
//
////////////////////////////////////////////////////////////////////////////////
// }}}
// Copyright (C) 2015-2025, Gisselquist Technology, LLC
// {{{
// This program is free software (firmware): you can redistribute it and/or
// modify it under the terms of the GNU General Public License as published
// by the Free Software Foundation, either version 3 of the License, or (at
// your option) any later version.
//
// This program is distributed in the hope that it will be useful, but WITHOUT
// ANY WARRANTY; without even the implied warranty of MERCHANTIBILITY or
// FITNESS FOR A PARTICULAR PURPOSE.  See the GNU General Public License
// for more details.
//
// You should have received a copy of the GNU General Public License along
// with this program.  (It's in the $(ROOT)/doc directory.  Run make with no
// target there if the PDF file isn't present.)  If not, see
// <http://www.gnu.org/licenses/> for a copy.
// }}}
// License:	GPL, v3, as defined and found on www.gnu.org,
// {{{
//		http://www.gnu.org/licenses/gpl.html
//
////////////////////////////////////////////////////////////////////////////////
//
`default_nettype	none
// }}}
module	memops #(
		// {{{
		parameter	ADDRESS_WIDTH=28,
		parameter	DATA_WIDTH=32,	// CPU's register width
		parameter	BUS_WIDTH=32,
		parameter [0:0]	OPT_LOCK=1'b1,
				WITH_LOCAL_BUS=1'b1,
				OPT_ALIGNMENT_ERR=1'b1,
				OPT_LOWPOWER=1'b0,
				OPT_LITTLE_ENDIAN = 1'b0,
		localparam	AW=ADDRESS_WIDTH
`ifdef	FORMAL
		, parameter	F_LGDEPTH = 2
`endif
		// }}}
	) (
		// {{{
		input	wire			i_clk, i_reset,
		// CPU interface
		// {{{
		input	wire			i_stb, i_lock,
		input	wire	[2:0]		i_op,
		input	wire	[31:0]		i_addr,
		input	wire [DATA_WIDTH-1:0]	i_data,
		input	wire	[4:0]		i_oreg,
		// CPU outputs
		output	wire			o_busy,
		output	reg			o_rdbusy,
		output	reg			o_valid,
		output	reg			o_err,
		output	reg	[4:0]		o_wreg,
		output	reg [DATA_WIDTH-1:0]	o_result,
		// }}}
		// Wishbone
		// {{{
		output	wire			o_wb_cyc_gbl,
		output	wire			o_wb_cyc_lcl,
		output	reg			o_wb_stb_gbl,
		output	reg			o_wb_stb_lcl,
		output	reg			o_wb_we,
		output	reg	[AW-1:0]	o_wb_addr,
		output	reg	[BUS_WIDTH-1:0]	o_wb_data,
		output	reg [BUS_WIDTH/8-1:0]	o_wb_sel,
		// Wishbone inputs
		input	wire			i_wb_stall, i_wb_ack, i_wb_err,
		input	wire	[BUS_WIDTH-1:0]	i_wb_data
		// }}}
		// }}}
	);

	// Declarations
	// {{{
	localparam	WBLSB = $clog2(BUS_WIDTH/8);
`ifdef	FORMAL
	wire	[(F_LGDEPTH-1):0]	f_nreqs, f_nacks, f_outstanding;
`endif

	wire		misaligned;
	reg		r_wb_cyc_gbl, r_wb_cyc_lcl;
	reg	[2+WBLSB-1:0]	r_op;
	wire		lock_gbl, lock_lcl;
	wire		lcl_bus, gbl_stb, lcl_stb;

	reg	[BUS_WIDTH/8-1:0]	oword_sel;
	wire	[BUS_WIDTH/8-1:0]	pre_sel;
	wire	[BUS_WIDTH-1:0]		pre_result;

	wire	[1:0]		oshift2;
	wire	[WBLSB-1:0]	oshift;

	// }}}

	// misaligned
	// {{{
	generate if (OPT_ALIGNMENT_ERR)
	begin : GENERATE_ALIGNMENT_ERR
		reg	r_misaligned;

		always @(*)
		casez({ i_op[2:1], i_addr[1:0] })
		4'b01?1: r_misaligned = i_stb; // Words must be halfword aligned
		4'b0110: r_misaligned = i_stb; // Words must be word aligned
		4'b10?1: r_misaligned = i_stb; // Halfwords must be aligned
		// 4'b11??: r_misaligned <= 1'b0; Byte access are never misaligned
		default: r_misaligned = 1'b0;
		endcase

		assign	misaligned = r_misaligned;
	end else begin : NO_MISALIGNMENT_ERR
		assign	misaligned = 1'b0;
	end endgenerate
	// }}}

	// lcl_stb, gbl_stb
	// {{{
	assign	lcl_bus = (WITH_LOCAL_BUS)&&(i_addr[31:24]==8'hff);
	assign	lcl_stb = (i_stb)&&( lcl_bus)&&(!misaligned);
	assign	gbl_stb = (i_stb)&&(!lcl_bus)&&(!misaligned);
	// }}}

	// r_wb_cyc_gbl, r_wb_cyc_lcl
	// {{{
	initial	r_wb_cyc_gbl = 1'b0;
	initial	r_wb_cyc_lcl = 1'b0;
	always @(posedge i_clk)
	if (i_reset)
	begin
		r_wb_cyc_gbl <= 1'b0;
		r_wb_cyc_lcl <= 1'b0;
	end else if ((r_wb_cyc_gbl)||(r_wb_cyc_lcl))
	begin
		if ((i_wb_ack)||(i_wb_err))
		begin
			r_wb_cyc_gbl <= 1'b0;
			r_wb_cyc_lcl <= 1'b0;
		end
	end else begin // New memory operation
		// Grab the wishbone
		r_wb_cyc_lcl <= (lcl_stb);
		r_wb_cyc_gbl <= (gbl_stb);
	end
	// }}}

	// o_wb_stb_gbl
	// {{{
	initial	o_wb_stb_gbl = 1'b0;
	always @(posedge i_clk)
	if (i_reset)
		o_wb_stb_gbl <= 1'b0;
	else if ((i_wb_err)&&(r_wb_cyc_gbl))
		o_wb_stb_gbl <= 1'b0;
	else if (gbl_stb)
		o_wb_stb_gbl <= 1'b1;
	else if (o_wb_cyc_gbl)
		o_wb_stb_gbl <= (o_wb_stb_gbl)&&(i_wb_stall);
	//  }}}

	// o_wb_stb_lcl
	// {{{
	initial	o_wb_stb_lcl = 1'b0;
	always @(posedge i_clk)
	if (i_reset)
		o_wb_stb_lcl <= 1'b0;
	else if ((i_wb_err)&&(r_wb_cyc_lcl))
		o_wb_stb_lcl <= 1'b0;
	else if (lcl_stb)
		o_wb_stb_lcl <= 1'b1;
	else if (o_wb_cyc_lcl)
		o_wb_stb_lcl <= (o_wb_stb_lcl)&&(i_wb_stall);
	// }}}

	// o_wb_we, o_wb_data, o_wb_sel
	// {{{
	always @(*)
	begin
		oword_sel = 0;

		casez({ OPT_LITTLE_ENDIAN, i_op[2:1], i_addr[1:0] })
		5'b00???: oword_sel[3:0] = 4'b1111;
		5'b0100?: oword_sel[3:0] = 4'b1100;
		5'b0101?: oword_sel[3:0] = 4'b0011;
		5'b01100: oword_sel[3:0] = 4'b1000;
		5'b01101: oword_sel[3:0] = 4'b0100;
		5'b01110: oword_sel[3:0] = 4'b0010;
		5'b01111: oword_sel[3:0] = 4'b0001;
		//
		// verilator coverage_off
		5'b10???: oword_sel[3:0] = 4'b1111;
		5'b1100?: oword_sel[3:0] = 4'b0011;
		5'b1101?: oword_sel[3:0] = 4'b1100;
		5'b11100: oword_sel[3:0] = 4'b0001;
		5'b11101: oword_sel[3:0] = 4'b0010;
		5'b11110: oword_sel[3:0] = 4'b0100;
		5'b11111: oword_sel[3:0] = 4'b1000;
		// verilator coverage_on
		//
		default: oword_sel[3:0] = 4'b1111;
		endcase
	end

	// pre_sel
	// {{{
	generate if (BUS_WIDTH == 32)
	begin : COPY_PRESEL
		assign	pre_sel = oword_sel;
	end else if (OPT_LITTLE_ENDIAN)
	begin : GEN_LILPRESEL
		wire	[WBLSB-3:0]	shift;

		assign	shift = i_addr[WBLSB-1:2];
		assign	pre_sel = oword_sel << (4 * i_addr[WBLSB-1:2]);
	end else begin : GEN_PRESEL
		wire	[WBLSB-3:0]	shift;

		assign	shift = {(WBLSB-2){1'b1}} ^ i_addr[WBLSB-1:2];
		assign	pre_sel = oword_sel << (4 * shift);
	end endgenerate
	// }}}

	assign	oshift  = i_addr[WBLSB-1:0];
	assign	oshift2 = i_addr[1:0];

	initial	o_wb_we   = 1'b0;
	initial	o_wb_data = 0;
	initial	o_wb_sel  = 0;
	always @(posedge i_clk)
	if (i_stb)
	begin
		o_wb_we   <= i_op[0];
		if (OPT_LOWPOWER)
		begin
			if (lcl_bus)
			begin
				// {{{
				o_wb_data <= 0;
				casez({ OPT_LITTLE_ENDIAN, i_op[2:1] })
				3'b010: o_wb_data[31:0] <= { i_data[15:0], {(16){1'b0}} } >> (8*oshift2);
				3'b011: o_wb_data[31:0] <= { i_data[ 7:0], {(24){1'b0}} } >> (8*oshift2);
				3'b00?: o_wb_data[31:0] <= i_data[31:0];
				//
				// verilator coverage_off
				3'b110: o_wb_data <= { {(BUS_WIDTH-16){1'b0}}, i_data[15:0] } << (8*oshift2);
				3'b111: o_wb_data <= { {(BUS_WIDTH-8){1'b0}},  i_data[ 7:0] } << (8*oshift2);
				3'b10?: o_wb_data <= { {(BUS_WIDTH-32){1'b0}}, i_data[31:0] } << (8*oshift2);
				// verilator coverage_on
				//
				endcase
				// }}}
			end else begin
				// {{{
				casez({ OPT_LITTLE_ENDIAN, i_op[2:1] })
				3'b010: o_wb_data <= { i_data[15:0], {(BUS_WIDTH-16){1'b0}} } >> (8*oshift);
				3'b011: o_wb_data <= { i_data[ 7:0], {(BUS_WIDTH- 8){1'b0}} } >> (8*oshift);
				3'b00?: o_wb_data <= { i_data[31:0], {(BUS_WIDTH-32){1'b0}} } >> (8*oshift);
				//
				3'b110: o_wb_data <= { {(BUS_WIDTH-16){1'b0}}, i_data[15:0] } << (8*oshift);
				3'b111: o_wb_data <= { {(BUS_WIDTH-8){1'b0}},  i_data[ 7:0] } << (8*oshift);
				3'b10?: o_wb_data <= { {(BUS_WIDTH-32){1'b0}}, i_data[31:0] } << (8*oshift);
				//
				endcase
				// }}}
			end
		end else
			casez({ i_op[2:1] })
			2'b10: o_wb_data <= { (BUS_WIDTH/16){ i_data[15:0] } };
			2'b11: o_wb_data <= { (BUS_WIDTH/ 8){ i_data[7:0] } };
			default: o_wb_data <= {(BUS_WIDTH/32){i_data}};
			endcase

		if (lcl_bus)
		begin
			o_wb_addr <= i_addr[2 +: (AW+2>32 ? (32-2) : AW)];
			o_wb_sel <= oword_sel;
		end else begin
			o_wb_addr <= i_addr[WBLSB +: (AW+WBLSB>32 ? (32-WBLSB) : AW)];
			o_wb_sel <= pre_sel;
		end

		r_op <= { i_op[2:1] , i_addr[WBLSB-1:0] };
	end else if ((OPT_LOWPOWER)&&(!o_wb_cyc_gbl)&&(!o_wb_cyc_lcl))
	begin
		o_wb_we   <= 1'b0;
		o_wb_addr <= 0;
		o_wb_data <= {(BUS_WIDTH){1'b0}};
		o_wb_sel  <= {(BUS_WIDTH/8){1'b0}};
	end
	// }}}

	// o_valid
	// {{{
	initial	o_valid = 1'b0;
	always @(posedge i_clk)
	if (i_reset)
		o_valid <= 1'b0;
	else
		o_valid <= (((o_wb_cyc_gbl)||(o_wb_cyc_lcl))
				&&(i_wb_ack)&&(!o_wb_we));
	// }}}

	// o_err
	// {{{
	initial	o_err = 1'b0;
	always @(posedge i_clk)
	if (i_reset)
		o_err <= 1'b0;
	else if ((r_wb_cyc_gbl)||(r_wb_cyc_lcl))
		o_err <= i_wb_err;
	else if ((i_stb)&&(!o_busy))
		o_err <= misaligned;
	else
		o_err <= 1'b0;
	// }}}

	assign	o_busy = (r_wb_cyc_gbl)||(r_wb_cyc_lcl);

	// o_rdbusy
	// {{{
	initial	o_rdbusy = 1'b0;
	always @(posedge i_clk)
	if (i_reset|| ((o_wb_cyc_gbl || o_wb_cyc_lcl)&&(i_wb_err || i_wb_ack)))
		o_rdbusy <= 1'b0;
	else if (i_stb && !i_op[0] && !misaligned)
		o_rdbusy <= 1'b1;
	else if (o_valid)
		o_rdbusy <= 1'b0;
	// }}}

	always @(posedge i_clk)
	if (i_stb)
		o_wreg    <= i_oreg;

	// o_result
	// {{{
	generate if (OPT_LITTLE_ENDIAN)
	begin : LILEND_RESULT

		assign	pre_result = i_wb_data >> (8*r_op[$clog2(BUS_WIDTH/8)-1:0]);

	end else begin : BIGEND_RESULT

		assign	pre_result = i_wb_data << (8*r_op[$clog2(BUS_WIDTH/8)-1:0]);

	end endgenerate

	always @(posedge i_clk)
	if ((OPT_LOWPOWER)&&(!i_wb_ack))
		o_result <= 32'h0;
	else if (o_wb_cyc_lcl && (BUS_WIDTH != 32))
	begin
		// The Local bus is naturally (and only) a 32-bit bus
		casez({ OPT_LITTLE_ENDIAN, r_op[WBLSB +: 2], r_op[1:0] })
		5'b?01??: o_result <= i_wb_data[31:0];
		//
		// Big endian
		5'b0100?: o_result <= { 16'h00, i_wb_data[31:16] };
		5'b0101?: o_result <= { 16'h00, i_wb_data[15: 0] };
		5'b01100: o_result <= { 24'h00, i_wb_data[31:24] };
		5'b01101: o_result <= { 24'h00, i_wb_data[23:16] };
		5'b01110: o_result <= { 24'h00, i_wb_data[15: 8] };
		5'b01111: o_result <= { 24'h00, i_wb_data[ 7: 0] };
		//
		// Little endian : Same bus result, just grab a different bits
		//   from the bus return to send back to the CPU.
		// verilator coverage_off
		5'b1100?: o_result <= { 16'h00, i_wb_data[15: 0] };
		5'b1101?: o_result <= { 16'h00, i_wb_data[31:16] };
		5'b11100: o_result <= { 24'h00, i_wb_data[ 7: 0] };
		5'b11101: o_result <= { 24'h00, i_wb_data[15: 8] };
		5'b11110: o_result <= { 24'h00, i_wb_data[23:16] };
		5'b11111: o_result <= { 24'h00, i_wb_data[31:24] };
		// verilator coverage_on
		default: o_result <= i_wb_data[31:0];
		endcase
	end else begin
		casez({ OPT_LITTLE_ENDIAN, r_op[$clog2(BUS_WIDTH/8) +: 2] })
		// Word
		//
		// Big endian
		3'b00?: o_result <= pre_result[BUS_WIDTH-1:BUS_WIDTH-32];
		3'b010: o_result <= { 16'h00, pre_result[BUS_WIDTH-1:BUS_WIDTH-16] };
		3'b011: o_result <= { 24'h00, pre_result[BUS_WIDTH-1:BUS_WIDTH-8] };
		//
		// Little endian : Same bus result, just grab a different bits
		//   from the bus return to send back to the CPU.
		// verilator coverage_off
		3'b10?: o_result <= pre_result[31: 0];
		3'b110: o_result <= { 16'h00, pre_result[15: 0] };
		3'b111: o_result <= { 24'h00, pre_result[ 7: 0] };
		// verilator coverage_on
		//
		// Just to have an (unused) default
		// default: o_result <= pre_result[31:0]; (Messes w/ coverage)
		endcase
	end
	// }}}

	// lock_gbl and lock_lcl
	// {{{
	generate
	if (OPT_LOCK)
	begin : GEN_LOCK
		// {{{
		reg	r_lock_gbl, r_lock_lcl;

		initial	r_lock_gbl = 1'b0;
		initial	r_lock_lcl = 1'b0;

		always @(posedge i_clk)
		if (i_reset)
		begin
			r_lock_gbl <= 1'b0;
			r_lock_lcl <= 1'b0;
		end else if (((i_wb_err)&&((r_wb_cyc_gbl)||(r_wb_cyc_lcl)))
				||(misaligned))
		begin
			// Kill the lock if
			//	there's a bus error, or
			//	User requests a misaligned memory op
			r_lock_gbl <= 1'b0;
			r_lock_lcl <= 1'b0;
		end else begin
			// Kill the lock if
			//	i_lock goes down
			//	User starts on the global bus, then switches
			//	  to local or vice versa
			r_lock_gbl <= (i_lock)&&((r_wb_cyc_gbl)||(lock_gbl))
					&&(!lcl_stb);
			r_lock_lcl <= (i_lock)&&((r_wb_cyc_lcl)||(lock_lcl))
					&&(!gbl_stb);
		end

		assign	lock_gbl = r_lock_gbl;
		assign	lock_lcl = r_lock_lcl;

		assign	o_wb_cyc_gbl = (r_wb_cyc_gbl)||(lock_gbl);
		assign	o_wb_cyc_lcl = (r_wb_cyc_lcl)||(lock_lcl);
		// }}}
	end else begin : NO_LOCK
		// {{{
		assign	o_wb_cyc_gbl = (r_wb_cyc_gbl);
		assign	o_wb_cyc_lcl = (r_wb_cyc_lcl);

		assign	{ lock_gbl, lock_lcl } = 2'b00;

		// Make verilator happy
		// verilator lint_off UNUSED
		wire	[2:0]	lock_unused;
		assign	lock_unused = { i_lock, lock_gbl, lock_lcl };
		// verilator lint_on  UNUSED
		// }}}
	end endgenerate
	// }}}

`ifdef	VERILATOR
	always @(posedge i_clk)
	if ((r_wb_cyc_gbl)||(r_wb_cyc_lcl))
		assert(!i_stb);
`endif


	// Make verilator happy
	// {{{
	// verilator coverage_off
	// verilator lint_off UNUSED
	wire	unused;
	assign	unused = &{ 1'b0, pre_result };
	generate if (AW < 22)
	begin : TOO_MANY_ADDRESS_BITS

		wire	[(21-AW):0] unused_addr;
		assign	unused_addr = i_addr[23:(AW+2)];

	end endgenerate
	// verilator lint_on  UNUSED
	// verilator coverage_on
	// }}}
////////////////////////////////////////////////////////////////////////////////
////////////////////////////////////////////////////////////////////////////////
////////////////////////////////////////////////////////////////////////////////
//
// Formal properties
// {{{
////////////////////////////////////////////////////////////////////////////////
////////////////////////////////////////////////////////////////////////////////
////////////////////////////////////////////////////////////////////////////////
`ifdef	FORMAL
`define	ASSERT	assert
`ifdef	MEMOPS
`define	ASSUME	assume
`else
`define	ASSUME	assert
`endif
	reg	f_past_valid;

	reg	[2:0]		fcpu_op;
	reg	[31:0]		fcpu_addr, fcpu_data;;
	reg	[BUS_WIDTH-1:0]	fbus_data, fpre_data;
	reg [$clog2(BUS_WIDTH/8)-1:0] fcpu_shift;
	reg			fcpu_local, fcpu_misaligned;
	reg	[BUS_WIDTH/8-1:0]	fbus_sel, fpre_sel;

	initial	f_past_valid = 0;
	always @(posedge i_clk)
		f_past_valid <= 1'b1;

	always @(*)
	if (!f_past_valid)
		`ASSUME(i_reset);

	////////////////////////////////////////////////////////////////////////
	//
	// Bus properties
	// {{{
	////////////////////////////////////////////////////////////////////////
	//
	//
	initial	`ASSUME(!i_stb);

	wire	f_cyc, f_stb;
	assign	f_cyc = (o_wb_cyc_gbl)||(o_wb_cyc_lcl);
	assign	f_stb = (o_wb_stb_gbl)||(o_wb_stb_lcl);

	fwb_master #(
		// {{{
		.AW(AW), .F_LGDEPTH(F_LGDEPTH), .DW(BUS_WIDTH),
		.F_OPT_RMW_BUS_OPTION(OPT_LOCK),
		.F_OPT_DISCONTINUOUS(OPT_LOCK)
		// }}}
	) f_wb(
		// {{{
		i_clk, i_reset,
		f_cyc, f_stb, o_wb_we, o_wb_addr, o_wb_data, o_wb_sel,
		i_wb_ack, i_wb_stall, i_wb_data, i_wb_err,
		f_nreqs, f_nacks, f_outstanding
		// }}}
	);


	// Rule: Only one of the two CYC's may be valid, never both
	always @(posedge i_clk)
		`ASSERT((!o_wb_cyc_gbl)||(!o_wb_cyc_lcl));

	// Rule: Only one of the two STB's may be valid, never both
	always @(posedge i_clk)
		`ASSERT((!o_wb_stb_gbl)||(!o_wb_stb_lcl));

	// Rule: if WITH_LOCAL_BUS is ever false, neither the local STB nor CYC
	// may be valid
	always @(*)
	if (!WITH_LOCAL_BUS)
	begin
		`ASSERT(!o_wb_cyc_lcl);
		`ASSERT(!o_wb_stb_lcl);
	end

	// Rule: If the global CYC is ever true, the LCL one cannot be true
	// on the next clock without an intervening idle of both
	always @(posedge i_clk)
	if ((f_past_valid)&&($past(r_wb_cyc_gbl)))
		`ASSERT(!r_wb_cyc_lcl);

	// Same for if the LCL CYC is true
	always @(posedge i_clk)
	if ((f_past_valid)&&($past(r_wb_cyc_lcl)))
		`ASSERT(!r_wb_cyc_gbl);

	// STB can never be true unless CYC is also true
	always @(posedge i_clk)
	if (o_wb_stb_gbl)
		`ASSERT(r_wb_cyc_gbl);

	always @(posedge i_clk)
	if (o_wb_stb_lcl)
		`ASSERT(r_wb_cyc_lcl);

	// This core only ever has zero or one outstanding transaction(s)
	always @(posedge i_clk)
	if ((o_wb_stb_gbl)||(o_wb_stb_lcl))
	begin
		`ASSERT(f_outstanding == 0);
	end else
		`ASSERT((f_outstanding == 0)||(f_outstanding == 1));

	// The LOCK function only allows up to two transactions (at most)
	// before CYC must be dropped.
	always @(posedge i_clk)
	if ((o_wb_stb_gbl)||(o_wb_stb_lcl))
	begin
		if (OPT_LOCK)
		begin
			`ASSERT((f_outstanding == 0)||(f_outstanding == 1));
		end else
			`ASSERT(f_nreqs <= 1);
	end
	// }}}
	////////////////////////////////////////////////////////////////////////
	//
	// CPU properties
	// {{{
	////////////////////////////////////////////////////////////////////////
	//
	//
	reg				f_done;
	wire	[(F_LGDEPTH-1):0]	cpu_outstanding;
	wire				f_pc, f_rdbusy, f_gie, f_read_cycle;
	wire	[4:0]			f_last_reg;
	wire	[4:0]			f_addr_reg;
	// Verilator lint_off UNDRIVEN
	(* anyseq *)	reg	[4:0]	f_areg;
	// Verilator lint_on  UNDRIVEN

	assign	f_rdbusy = f_cyc && (f_stb || f_outstanding > 0) && !o_wb_we;

	initial	f_done = 1'b0;
	always @(posedge i_clk)
	if (i_reset)
		f_done <= 1'b0;
	else
		f_done <= ((o_wb_cyc_gbl)||(o_wb_cyc_lcl))&&(i_wb_ack);

	fmem #(
		// {{{
		.F_LGDEPTH(F_LGDEPTH),
		.OPT_LOCK(OPT_LOCK),
		.OPT_MAXDEPTH(1)
		// }}}
	) fmemi(
		// {{{
		.i_clk(i_clk),
		.i_sys_reset(i_reset),
		.i_cpu_reset(i_reset),
		.i_stb(i_stb),
		.i_pipe_stalled(o_busy),
		.i_clear_cache(1'b0),
		.i_lock(i_lock),
		.i_op(i_op), .i_addr(i_addr), .i_data(i_data), .i_oreg(i_oreg),
		.i_areg(f_areg),
		.i_busy(o_busy),
		.i_rdbusy(f_rdbusy),
		.i_valid(o_valid), .i_done(f_done), .i_err(o_err),
		.i_wreg(o_wreg), .i_result(o_result),
		.f_outstanding(cpu_outstanding),
		.f_pc(f_pc),
		.f_gie(f_gie),
		.f_read_cycle(f_read_cycle),
		.f_last_reg(f_last_reg), .f_addr_reg(f_addr_reg)
		// }}}
	);

	always @(*)
	if (!o_err)
		assert(cpu_outstanding == f_outstanding + (f_stb ? 1:0)
					+ ((f_done || o_err) ? 1:0));

	always @(*)
		assert(cpu_outstanding <= 1);

	always @(*)
	if (f_pc)
	begin
		assert(o_wreg[3:1] == 3'h7);
	end else if (f_rdbusy)
		assert(o_wreg[3:1] != 3'h7);

	always @(*)
	if (o_busy)
		assert(o_wreg[4] == f_gie);

	always @(*)
	if (!o_err)
		assert(f_rdbusy == o_rdbusy);

	always @(*)
	if (o_busy)
		assert(o_wb_we == !f_read_cycle);

	always @(*)
	if (cpu_outstanding > 0)
		assert(f_last_reg == o_wreg);
	// }}}
	////////////////////////////////////////////////////////////////////////
	//
	// Tying the two together
	// {{{
	////////////////////////////////////////////////////////////////////////
	//
	//

	// Following any i_stb request, assuming we are idle, immediately
	// begin a bus transaction
	always @(posedge i_clk)
	if ((f_past_valid)&&($past(i_stb))
		&&(!$past(f_cyc))&&(!$past(i_reset)))
	begin
		if ($past(misaligned))
		begin
			`ASSERT(!f_cyc);
			`ASSERT(!o_busy);
			`ASSERT(o_err);
			`ASSERT(!o_valid);
		end else begin
			`ASSERT(f_cyc);
			`ASSERT(o_busy);
		end
	end

//	always @(posedge i_clk)
//	if (o_busy)
//		`ASSUME(!i_stb);

	always @(*)
	if (o_err || o_valid)
		`ASSERT(!o_busy);

	always @(posedge i_clk)
	if (o_wb_cyc_gbl)
		`ASSERT((o_busy)||(lock_gbl));

	always @(posedge i_clk)
	if (o_wb_cyc_lcl)
		`ASSERT((o_busy)||(lock_lcl));

	always @(posedge i_clk)
	if (f_outstanding > 0)
		`ASSERT(o_busy);

	// If a transaction ends in an error, send o_err on the output port.
	always @(posedge i_clk)
	if (f_past_valid && !$past(i_reset))
	begin
		if (($past(f_cyc))&&($past(i_wb_err)))
		begin
			`ASSERT(o_err);
		end else if ($past(misaligned))
			`ASSERT(o_err);
	end

	// Always following a successful ACK, return an O_VALID value.
	always @(posedge i_clk)
	if (f_past_valid && !$past(i_reset))
	begin
		if(($past(f_cyc))&&($past(i_wb_ack))
				&&(!$past(o_wb_we)))
		begin
			`ASSERT(o_valid);
		end else if ($past(misaligned))
		begin
			`ASSERT((!o_valid)&&(o_err));
		end else
			`ASSERT(!o_valid);
	end

	always @(posedge i_clk)
	if (i_stb)
	begin
		fcpu_op   <= i_op;
		fcpu_addr <= i_addr;
		fcpu_data <= i_data;
	end

	always @(*)
	begin
		fcpu_local = (&fcpu_addr[31:24]) && WITH_LOCAL_BUS;

		if (OPT_LITTLE_ENDIAN)
		begin
			// {{{
			casez(fcpu_op[2:1])
			2'b11: fpre_sel = { {(BUS_WIDTH/8-1){1'b0}}, 1'b1 };
			2'b10: fpre_sel = { {(BUS_WIDTH/8-2){1'b0}}, 2'b11 };
			2'b0?: fpre_sel = { {(BUS_WIDTH/8-4){1'b0}}, 4'b1111 };
			endcase

			casez(fcpu_op[2:1])
			2'b11: fpre_data = { {(BUS_WIDTH- 8){1'b0}}, fcpu_data[ 7:0] };
			2'b10: fpre_data = { {(BUS_WIDTH-16){1'b0}}, fcpu_data[15:0] };
			2'b0?: fpre_data = { {(BUS_WIDTH-32){1'b0}}, fcpu_data[31:0] };
			endcase
			// }}}
		end else if (fcpu_local)
		begin
			// {{{
			fpre_sel = 0;
			casez(fcpu_op[2:1])
			2'b11: fpre_sel[3:0] = 4'b1000;
			2'b10: fpre_sel[3:0] = 4'b1100;
			2'b0?: fpre_sel[3:0] = 4'b1111;
			endcase

			fpre_data = 0;
			casez(fcpu_op[2:1])
			2'b11: fpre_data[31:0] = { fcpu_data[ 7:0], {(24){1'b0}} };
			2'b10: fpre_data[31:0] = { fcpu_data[15:0], {(16){1'b0}} };
			2'b0?: fpre_data[31:0] = fcpu_data[31:0];
			endcase
			// }}}
		end else begin
			// {{{
			casez(fcpu_op[2:1])
			2'b11: fpre_sel = { 1'b1,    {(BUS_WIDTH/8-1){1'b0}} };
			2'b10: fpre_sel = { 2'b11,   {(BUS_WIDTH/8-2){1'b0}} };
			2'b0?: fpre_sel = { 4'b1111, {(BUS_WIDTH/8-4){1'b0}} };
			endcase

			casez(fcpu_op[2:1])
			2'b11: fpre_data = { fcpu_data[ 7:0], {(BUS_WIDTH- 8){1'b0}} };
			2'b10: fpre_data = { fcpu_data[15:0], {(BUS_WIDTH-16){1'b0}} };
			2'b0?: fpre_data = { fcpu_data[31:0], {(BUS_WIDTH-32){1'b0}} };
			endcase
			// }}}
		end


		casez({ fcpu_op[2:1], fcpu_addr[1:0] })
		4'b01?1: fcpu_misaligned = 1'b1; // Words must be halfword aligned
		4'b0110: fcpu_misaligned = 1'b1; // Words must be word aligned
		4'b10?1: fcpu_misaligned = 1'b1; // Halfwords must be aligned
		// 4'b11??: fcpu_misaligned <= 1'b0; Byte access are never misaligned
		default: fcpu_misaligned = 1'b0;
		endcase

		if (fcpu_local)
		begin
			fcpu_shift = fcpu_addr[1:0];
			if (OPT_LITTLE_ENDIAN)
			begin
				fbus_sel   = fpre_sel  << fcpu_shift;
				fbus_data  = fpre_data << (8*fcpu_shift);
			end else begin
				fbus_sel   = fpre_sel  >> (fcpu_shift + (DATA_WIDTH/8-4));
				fbus_data  = fpre_data >> (8*(fcpu_shift + (DATA_WIDTH/8-4)));
			end
		end else begin
			fcpu_shift = fcpu_addr[WBLSB-1:0];
			if (OPT_LITTLE_ENDIAN)
			begin
				fbus_sel  = fpre_sel  << fcpu_shift;
				fbus_data = fpre_data << (8*fcpu_shift);
			end else begin
				fbus_sel  = fpre_sel  >> fcpu_shift;
				fbus_data = fpre_data >> (8*fcpu_shift);
			end
		end

		if (!OPT_LOWPOWER)
		casez(fcpu_op[2:1])
		2'b11: fbus_data = {(BUS_WIDTH/ 8){fcpu_data[ 7:0] } };
		2'b10: fbus_data = {(BUS_WIDTH/16){fcpu_data[15:0] } };
		2'b0?: fbus_data = {(BUS_WIDTH/32){fcpu_data[31:0] } };
		endcase
	end

	always @(*)
	if (OPT_ALIGNMENT_ERR && fcpu_misaligned)
		assert(!o_valid && !f_cyc);

	always @(*)
	if (f_stb)
	begin
		if (fcpu_local)
		begin
			assert(o_wb_stb_lcl);
			assert(o_wb_addr == fcpu_addr[AW+1:2]);
		end else begin
			assert(o_wb_stb_gbl);
			assert(o_wb_addr == fcpu_addr[WBLSB +: AW]);
		end

		if (fcpu_op[0])
		begin
			`ASSERT(o_wb_we);
			`ASSERT(fcpu_misaligned || o_wb_sel  == fbus_sel);
			`ASSERT(fcpu_misaligned || o_wb_data == fbus_data);
		end else begin
			`ASSERT(!o_wb_we);
		end
	end

	always @(*)
	if (f_cyc)
		assert(o_wb_cyc_lcl == fcpu_local);

	initial	o_wb_we = 1'b0;
	always @(posedge i_clk)
	if ((f_past_valid)&&(!$past(i_reset))&&($past(i_stb)))
	begin
		// On a write, assert o_wb_we should be true
		assert( $past(i_op[0]) == o_wb_we);
	end

	always @(posedge i_clk)
	if (o_wb_stb_lcl)
		`ASSERT(fcpu_local);

	always @(posedge i_clk)
	if ((f_past_valid)&&(!$past(i_reset))&&($past(misaligned)))
	begin
		`ASSERT(!o_wb_cyc_gbl);
		`ASSERT(!o_wb_cyc_lcl);
		`ASSERT(!o_wb_stb_gbl);
		`ASSERT(!o_wb_stb_lcl);
		`ASSERT(o_err);
	end

//	always @(posedge i_clk)
//	if ((!f_past_valid)||($past(i_reset)))
//		`ASSUME(!i_stb);

	always @(posedge i_clk)
	if ((f_past_valid)&&(OPT_LOCK)
			&&(!$past(i_reset))&&(!$past(i_wb_err))
			&&(!$past(misaligned))
			&&(!$past(lcl_stb))
			&&($past(i_lock))&&($past(lock_gbl)))
		assert(lock_gbl);

	always @(posedge i_clk)
	if ((f_past_valid)&&(OPT_LOCK)
			&&(!$past(i_reset))&&(!$past(i_wb_err))
			&&(!$past(misaligned))
			&&(!$past(lcl_stb))
			&&($past(o_wb_cyc_gbl))&&($past(i_lock))
			&&($past(lock_gbl)))
		assert(o_wb_cyc_gbl);

	always @(posedge i_clk)
	if ((f_past_valid)&&(OPT_LOCK)
			&&(!$past(i_reset))&&(!$past(i_wb_err))
			&&(!$past(misaligned))
			&&(!$past(gbl_stb))
			&&($past(o_wb_cyc_lcl))&&($past(i_lock))
			&&($past(lock_lcl)))
		assert(o_wb_cyc_lcl);
	// }}}
	////////////////////////////////////////////////////////////////////////
	//
	// Cover properties
	// {{{
	////////////////////////////////////////////////////////////////////////
	//
	//
	always @(posedge i_clk)
		cover(i_wb_ack);

	// Cover a response on the same clock it is made
	always @(posedge i_clk)
		cover((o_wb_stb_gbl)&&(i_wb_ack));

	// Cover a response a clock later
	always @(posedge i_clk)
		cover((o_wb_stb_gbl)&&(i_wb_ack));

	always @(posedge i_clk)
		cover(f_done);

	always @(posedge i_clk)
		cover(f_done && !o_busy);

	generate if (WITH_LOCAL_BUS)
	begin

		// Same things on the local bus
		always @(posedge i_clk)
			cover((o_wb_cyc_lcl)&&(!o_wb_stb_lcl)&&(i_wb_ack));
		always @(posedge i_clk)
			cover((o_wb_stb_lcl)&&(i_wb_ack));

	end endgenerate
	// }}}

	// Make Verilator happy
	// {{{
	// Verilator lint_off UNUSED
	wire	unused;
	assign	unused = &{ 1'b0, f_nacks, f_addr_reg };
	// Verilator lint_on  UNUSED
	// }}}
`endif
// }}}
endmodule
//
//
// Usage (from yosys):
//		(BFOR)	(!ZOI,ALIGN)	(ZOI,ALIGN)	(!ZOI,!ALIGN)
//	Cells	 230		226		281		225
//	  FDRE	 114		116		116		116
//	  LUT2	  17		 23		 76		 19
//	  LUT3	   9		 23		 17		 20
//	  LUT4	  15		  4		 11		 14
//	  LUT5	  18		 18		  7		 15
//	  LUT6	  33		 18		 54		 38
//	  MUX7	  16		 12		  		  2
//	  MUX8	   8		  1				  1
//
//

content.content:
1	////////////////////////////////////////////////////////////////////////////////
2	//
3	// Filename:	rtl/core/dcache.v
4	// {{{
5	// Project:	Zip CPU -- a small, lightweight, RISC CPU soft core
6	//
7	// Purpose:	To provide a simple data cache for the ZipCPU.  The cache is
8	//		designed to be a drop in replacement for the pipememm memory
9	//	unit currently existing within the ZipCPU.  The goal of this unit is
10	//	to achieve single cycle read access to any memory in the last cache line
11	//	used, or two cycle access to any memory currently in the cache.
12	//
13	//	The cache separates between four types of accesses, one write and three
14	//	read access types.  The read accesses are split between those that are
15	//	not cacheable, those that are in the cache, and those that are not.
16	//
17	//	1. Write accesses always create writes to the bus.  For these reasons,
18	//		these may always be considered cache misses.
19	//
20	//		Writes to memory locations within the cache must also update
21	//		cache memory immediately, to keep the cache in synch.
22	//
23	//		It is our goal to be able to maintain single cycle write
24	//		accesses for memory bursts.
25	//
26	//	2. Read access to non-cacheable memory locations will also immediately
27	//		go to the bus, just as all write accesses go to the bus.
28	//
29	//	3. Read accesses to cacheable memory locations will immediately read
30	//		from the appropriate cache line.  However, since thee valid
31	//		line will take a second clock to read, it may take up to two
32	//		clocks to know if the memory was in cache.  For this reason,
33	//		we bypass the test for the last validly accessed cache line.
34	//
35	//		We shall design these read accesses so that reads to the cache
36	//		may take place concurrently with other writes to the bus.
37	//
38	//	Errors in cache reads will void the entire cache line.  For this reason,
39	//	cache lines must always be of a smaller in size than any associated
40	//	virtual page size--lest in the middle of reading a page a TLB miss
41	//	take place referencing only a part of the cacheable page.
42	//
43	//
44	//
45	//
46	// Creator:	Dan Gisselquist, Ph.D.
47	//		Gisselquist Technology, LLC
48	//
49	////////////////////////////////////////////////////////////////////////////////
50	// }}}
51	// Copyright (C) 2016-2025, Gisselquist Technology, LLC
52	// {{{
53	// This program is free software (firmware): you can redistribute it and/or
54	// modify it under the terms of the GNU General Public License as published
55	// by the Free Software Foundation, either version 3 of the License, or (at
56	// your option) any later version.
57	//
58	// This program is distributed in the hope that it will be useful, but WITHOUT
59	// ANY WARRANTY; without even the implied warranty of MERCHANTIBILITY or
60	// FITNESS FOR A PARTICULAR PURPOSE.  See the GNU General Public License
61	// for more details.
62	//
63	// You should have received a copy of the GNU General Public License along
64	// with this program.  (It's in the $(ROOT)/doc directory.  Run make with no
65	// target there if the PDF file isn't present.)  If not, see
66	// <http://www.gnu.org/licenses/> for a copy.
67	// }}}
68	// License:	GPL, v3, as defined and found on www.gnu.org,
69	// {{{
70	//		http://www.gnu.org/licenses/gpl.html
71	//
72	////////////////////////////////////////////////////////////////////////////////
73	//
74	`default_nettype	none
75	//
76	//
77	`ifdef	FORMAL
78	`define	ASSERT	assert
79	
80	`ifdef DCACHE
81	`define	ASSUME	assume
82	`else
83	`define	ASSUME	assert
84	`endif
85	`endif
86	 // }}}
87	module	dcache #(
88			// {{{
89			parameter	LGCACHELEN = 8,
90					BUS_WIDTH=32,
91					ADDRESS_WIDTH=32-$clog2(BUS_WIDTH/8),
92					LGNLINES=(LGCACHELEN-3), // Log of the number of separate cache lines
93					NAUX=5,	// # of aux d-wires to keep aligned w/memops
94			parameter	DATA_WIDTH=32, // CPU's register width
95			parameter [0:0]	OPT_LOCAL_BUS=1'b1,
96			parameter [0:0]	OPT_PIPE=1'b1,
97			parameter [0:0]	OPT_LOCK=1'b1,
98			parameter [0:0]	OPT_DUAL_READ_PORT=1'b1,
99			parameter 	OPT_FIFO_DEPTH = 4,
100			localparam	AW = ADDRESS_WIDTH, // Just for ease of notation below
101			localparam	CS = LGCACHELEN, // Number of bits in a cache address
102			localparam	LS = CS-LGNLINES, // Bits to spec position w/in cline
103	`ifdef	FORMAL
104			parameter	F_LGDEPTH=1 + (((!OPT_PIPE)||(LS > OPT_FIFO_DEPTH))
105							? LS : OPT_FIFO_DEPTH),
106	`endif
107			parameter [0:0]	OPT_LOWPOWER = 1'b0,
108			// localparam	DW = 32, // Bus data width
109			localparam	DP = OPT_FIFO_DEPTH,
110			localparam	WBLSB = $clog2(BUS_WIDTH/8),
111			// localparam	DLSB = $clog2(DATA_WIDTH/8),
112			//
113			localparam [1:0]	DC_IDLE  = 2'b00, // Bus is idle
114			localparam [1:0]	DC_WRITE = 2'b01, // Write
115			localparam [1:0]	DC_READS = 2'b10, // Read a single value(!cachd)
116			localparam [1:0]	DC_READC = 2'b11 // Read a whole cache line
117			// }}}
118		) (
119			// {{{
120			input	wire		i_clk, i_reset, i_clear,
121			// Interface from the CPU
122			// {{{
123			input	wire		i_pipe_stb, i_lock,
124			input	wire [2:0]	i_op,
125			input	wire [DATA_WIDTH-1:0]	i_addr,
126			input	wire [DATA_WIDTH-1:0]	i_data,
127			input	wire [(NAUX-1):0] i_oreg, // Aux data, such as reg to write to
128			// Outputs, going back to the CPU
129			output	reg		o_busy, o_rdbusy,
130			output	reg		o_pipe_stalled,
131			output	reg		o_valid, o_err,
132			output reg [(NAUX-1):0]	o_wreg,
133			output	reg [DATA_WIDTH-1:0]	o_data,
134			// }}}
135			// Wishbone bus master outputs
136			// {{{
137			output	wire		o_wb_cyc_gbl, o_wb_cyc_lcl,
138			output	reg		o_wb_stb_gbl, o_wb_stb_lcl,
139			output	reg		o_wb_we,
140			output	reg [(AW-1):0]	o_wb_addr,
141			output	reg [BUS_WIDTH-1:0]	o_wb_data,
142			output	wire [BUS_WIDTH/8-1:0]	o_wb_sel,
143			// Wishbone bus slave response inputs
144			input	wire			i_wb_stall, i_wb_ack, i_wb_err,
145			input	wire	[BUS_WIDTH-1:0]	i_wb_data
146			// }}}
147			// }}}
148		);
149	
150		// Declarations
151		// {{{
152		localparam	FIF_WIDTH = (NAUX-1)+2+WBLSB;
153		integer			ik;
154	
155	`ifdef FORMAL
156		wire [(F_LGDEPTH-1):0]	f_nreqs, f_nacks, f_outstanding;
157		wire			f_pc, f_gie, f_read_cycle;
158	
159		reg			f_past_valid;
160	`endif
161		//
162		// output	reg	[31:0]		o_debug;
163	
164		reg	cyc, stb, last_ack, end_of_line, last_line_stb;
165		reg	r_wb_cyc_gbl, r_wb_cyc_lcl;
166		// npending is the number of pending non-cached operations, counted
167		// from the i_pipe_stb to the o_wb_ack
168		reg	[DP:0]	npending;
169	
170	
171		reg	[((1<<LGNLINES)-1):0] c_v;	// One bit per cache line, is it valid?
172		reg	[(AW-LS-1):0]	c_vtags	[0:((1<<LGNLINES)-1)];
173		reg	[BUS_WIDTH-1:0]	c_mem	[0:((1<<CS)-1)];
174		reg			set_vflag;
175		reg	[1:0]		state;
176		reg	[(CS-1):0]	wr_addr;
177		reg	[BUS_WIDTH-1:0]		cached_iword, cached_rword;
178		reg			lock_gbl, lock_lcl;
179	
180	
181		// To simplify writing to the cache, and the job of the synthesizer to
182		// recognize that a cache write needs to take place, we'll take an extra
183		// clock to get there, and use these c_w... registers to capture the
184		// data in the meantime.
185		reg			c_wr;
186		reg	[BUS_WIDTH-1:0]	c_wdata;
187		reg [BUS_WIDTH/8-1:0]	c_wsel;
188		reg	[(CS-1):0]	c_waddr;
189	
190		reg	[(AW-LS-1):0]	last_tag;
191		reg			last_tag_valid;
192	
193	
194		wire	[(LGNLINES-1):0]	i_cline;
195		wire	[(CS-1):0]	i_caddr;
196	
197	`ifdef	FORMAL
198		reg	[F_LGDEPTH-1:0]	f_fill;
199		reg	[AW:0]		f_return_address;
200		reg	[AW:0]		f_pending_addr;
201		reg			f_pc_pending;
202		wire	[4:0]		f_last_reg, f_addr_reg;
203		// Verilator lint_off UNDRIVEN
204		(* anyseq *) reg [4:0]	f_areg;
205		// Verilator lint_on  UNDRIVEN
206	`endif
207		wire	cache_miss_inow, w_cachable;
208		wire	raw_cachable_address;
209		reg	r_cachable, r_svalid, r_dvalid, r_rd, r_cache_miss,
210			r_rd_pending;
211		reg	[AW-1:0]		r_addr;
212		wire	[(LGNLINES-1):0]	r_cline;
213		wire	[(CS-1):0]		r_caddr;
214		wire	[(AW-LS-1):0]		r_ctag;
215		reg	wr_cstb, r_iv, in_cache;
216		reg	[(AW-LS-1):0]	r_itag;
217		reg	[FIF_WIDTH:0]	req_data;
218		reg			gie;
219		reg	[BUS_WIDTH-1:0]	pre_data, pre_shifted;
220		// }}}
221	
222		// Convenience assignments
223		// {{{
224		assign	i_cline = i_addr[WBLSB +LS +: (CS-LS)];
225		assign	i_caddr = i_addr[WBLSB +: CS];
226	
227		assign	cache_miss_inow = (!last_tag_valid)
228					||(last_tag != i_addr[WBLSB+LS +: (AW-LS)])
229					||(!c_v[i_cline]);
230	
231		assign	w_cachable = ((!OPT_LOCAL_BUS)
232					||(i_addr[DATA_WIDTH-1:DATA_WIDTH-8]!=8'hff))
233			&&((!i_lock)||(!OPT_LOCK))&&(raw_cachable_address);
234	
235		assign	r_cline = r_addr[(CS-1):LS];
236		assign	r_caddr = r_addr[(CS-1):0];
237		assign	r_ctag  = r_addr[(AW-1):LS];
238		// }}}
239	
240		// Cachability checking
241		// {{{
242		iscachable chkaddress(i_addr[0 +: AW+WBLSB], raw_cachable_address);
243		// }}}
244	
245		// r_* values
246		// {{{
247		// The one-clock delayed read values from the cache.
248		//
249		initial	r_rd = 1'b0;
250		initial	r_cachable = 1'b0;
251		initial	r_svalid = 1'b0;
252		initial	r_dvalid = 1'b0;
253		initial	r_cache_miss = 1'b0;
254		initial	r_addr = 0;
255		initial	last_tag_valid = 0;
256		initial	r_rd_pending = 0;
257		always @(posedge i_clk)
258		begin
259			// The single clock path
260			// The valid for the single clock path
261			//	Only ... we need to wait if we are currently writing
262			//	to our cache.
263			r_svalid<= (i_pipe_stb)&&(!i_op[0])&&(w_cachable)
264					&&(!cache_miss_inow)&&(!c_wr)&&(!wr_cstb);
265	
266			//
267			// The two clock in-cache path
268			//
269			// Some preliminaries that needed to be calculated on the first
270			// clock
271			if ((!o_pipe_stalled)&&(!r_rd_pending))
272				r_addr <= i_addr[WBLSB +: AW];
273			if ((!o_pipe_stalled)&&(!r_rd_pending))
274			begin
275				r_iv   <= c_v[i_cline];
276				// r_itag <= c_vtags[i_cline];
277				r_cachable <= (!i_op[0])&&(w_cachable)&&(i_pipe_stb);
278				r_rd_pending <= (i_pipe_stb)&&(!i_op[0])&&(w_cachable)
279					&&((cache_miss_inow)||(c_wr)||(wr_cstb));
280					// &&((!c_wr)||(!wr_cstb));
281			end else begin
282				r_iv   <= c_v[r_cline];
283				// r_itag <= c_vtags[r_cline];
284				r_rd_pending <= (r_rd_pending)
285					&&((!cyc)||(!i_wb_err))
286					&&((r_itag != r_ctag)||(!r_iv));
287			end
288			r_rd <= (i_pipe_stb)&&(!i_op[0]);
289			// r_itag contains the tag we didn't have available to us on the
290			// last clock, r_ctag is a bit select from r_addr containing a
291			// one clock delayed address.
292			r_dvalid <= (!r_svalid)&&(!r_dvalid)&&(r_itag == r_ctag)&&(r_iv)
293							&&(r_cachable)&&(r_rd_pending);
294			if ((r_itag == r_ctag)&&(r_iv)&&(r_cachable)&&(r_rd_pending))
295			begin
296				last_tag_valid <= 1'b1;
297				last_tag <= r_ctag;
298			end else if ((state == DC_READC)
299					&&(last_tag[CS-LS-1:0]==r_addr[CS-1:LS])
300					&&((i_wb_ack)||(i_wb_err)))
301				last_tag_valid <= 1'b0;
302	
303			// r_cache miss takes a clock cycle.  It is only ever true for
304			// something that should be cachable, but isn't in the cache.
305			// A cache miss is only true _if_
306			// 1. A read was requested
307			// 2. It is for a cachable address, AND
308			// 3. It isn't in the cache on the first read
309			//	or the second read
310			// 4. The read hasn't yet started to get this address
311			r_cache_miss <= ((!cyc)||(o_wb_we))&&(r_cachable)
312					// One clock path -- miss
313					&&(!r_svalid)
314					// Two clock path -- misses as well
315					&&(r_rd)&&(!r_svalid)
316					&&((r_itag != r_ctag)||(!r_iv));
317	
318			if (i_clear)
319				last_tag_valid <= 0;
320			if (i_reset)
321			begin
322				// r_rd <= 1'b0;
323				r_cachable <= 1'b0;
324				r_svalid <= 1'b0;
325				r_dvalid <= 1'b0;
326				r_cache_miss <= 1'b0;
327				// r_addr <= 0;
328				r_rd_pending <= 0;
329				last_tag_valid <= 0;
330			end
331		end
332	
333		always @(posedge i_clk)
334			r_itag <= c_vtags[(!o_pipe_stalled && !r_rd_pending) ? i_cline : r_cline];
335		// }}}
336	
337		// o_wb_sel, r_sel
338		// {{{
339		generate if (DATA_WIDTH == BUS_WIDTH)
340		begin : COPY_SEL
341			// {{{
342			reg	[BUS_WIDTH/8-1:0]	r_sel;
343	
344			initial	r_sel = 4'hf;
345			always @(posedge i_clk)
346			if (i_reset)
347				r_sel <= 4'hf;
348			else if (!o_pipe_stalled && (!OPT_LOWPOWER  || i_pipe_stb))
349			begin
350				casez({i_op[2:1], i_addr[1:0]})
351				4'b0???: r_sel <= 4'b1111;
352				4'b100?: r_sel <= 4'b1100;
353				4'b101?: r_sel <= 4'b0011;
354				4'b1100: r_sel <= 4'b1000;
355				4'b1101: r_sel <= 4'b0100;
356				4'b1110: r_sel <= 4'b0010;
357				4'b1111: r_sel <= 4'b0001;
358				endcase
359			end else if (OPT_LOWPOWER && !i_wb_stall)
360				r_sel <= 4'h0;
361	
362			assign	o_wb_sel = (state == DC_READC) ? 4'hf : r_sel;
363			// }}}
364		end else begin : GEN_SEL
365			// {{{
366			reg	[DATA_WIDTH/8-1:0]	pre_sel;
367			reg	[BUS_WIDTH/8-1:0]	full_sel, r_wb_sel;
368	
369			always @(*)
370			casez(i_op[2:1])
371			2'b0?: pre_sel = {(DATA_WIDTH/8){1'b1}};
372			2'b10: pre_sel = { 2'b11, {(DATA_WIDTH/8-2){1'b0}} };
373			2'b11: pre_sel = { 1'b1,  {(DATA_WIDTH/8-1){1'b0}} };
374			endcase
375	
376			always @(*)
377			if (OPT_LOCAL_BUS && (&i_addr[31:24]))
378				full_sel = { {(BUS_WIDTH/8-4){1'b0}}, pre_sel }
379						>> (i_addr[1:0]);
380			else
381				full_sel = { pre_sel, {(BUS_WIDTH/8-4){1'b0}} }
382							>> (i_addr[WBLSB-1:0]);
383	
384			initial	r_wb_sel = -1;
385			always @(posedge i_clk)
386			if (i_reset)
387				r_wb_sel <= -1;
388			else if (i_pipe_stb && (i_op[0] || !w_cachable))
389				r_wb_sel <= full_sel;
390			else if (!i_wb_stall)
391				r_wb_sel <= -1;
392	
393			assign	o_wb_sel = r_wb_sel;
394			// }}}
395		end endgenerate
396		// }}}
397	
398		// o_wb_data
399		// {{{
400		generate if (DATA_WIDTH == BUS_WIDTH)
401		begin : GEN_SAME_BUSWIDTH
402			// {{{
403			initial	o_wb_data = 0;
404			always @(posedge i_clk)
405			if (i_reset)
406				o_wb_data <= 0;
407			else if ((!o_busy || !i_wb_stall) && (!OPT_LOWPOWER || i_pipe_stb))
408			begin
409				if (DATA_WIDTH == 32)
410				begin
411					if (OPT_LOWPOWER)
412					begin : ZERO_UNUSED_DATA_BITS
413						casez({ i_op[2:1], i_addr[1:0] })
414						4'b0???: o_wb_data <= i_data;
415						4'b100?: o_wb_data <= { i_data[15:0], 16'h0 };
416						4'b101?: o_wb_data <= { 16'h0, i_data[15:0] };
417						4'b1100: o_wb_data <= { i_data[7:0], 24'h0 };
418						4'b1101: o_wb_data <= {  8'h0, i_data[7:0], 16'h0 };
419						4'b1110: o_wb_data <= { 16'h0, i_data[7:0],  8'h0 };
420						4'b1111: o_wb_data <= { 24'h0, i_data[7:0] };
421						endcase
422					end else begin : DUPLICATE_UNUSED_DATA_BITS
423						casez(i_op[2:1])
424						2'b0?: o_wb_data <= i_data;
425						2'b10: o_wb_data <= { (2){i_data[15:0]} };
426						2'b11: o_wb_data <= { (4){i_data[ 7:0]} };
427						endcase
428					end
429				end else begin
430					// Verilator coverage_off
431					casez(i_op[2:1])
432					2'b0?: o_wb_data <= i_data << (8*i_addr[$clog2(DATA_WIDTH)-1:0]);
433					2'b10: o_wb_data <= { 16'h0, i_data[15:0] } << (8*i_addr[$clog2(DATA_WIDTH)-1:0]);
434					2'b11: o_wb_data <= { 24'h0, i_data[7:0] } << (8*i_addr[$clog2(DATA_WIDTH)-1:0]);
435					endcase
436					// Verilator coverage_on
437				end
438			end else if (OPT_LOWPOWER && !i_wb_stall)
439				o_wb_data <= 0;
440			// }}}
441		end else begin : GEN_WIDE_BUS
442			// {{{
443			reg	[DATA_WIDTH-1:0]	pre_shift;
444			reg	[BUS_WIDTH-1:0]		wide_preshift, shifted_data;
445	
446			always @(*)
447			begin
448				casez(i_op[2:1])
449				2'b0?: pre_shift = i_data;
450				2'b10: pre_shift = { i_data[15:0],
451							{(DATA_WIDTH-16){1'b0}} };
452				2'b11: pre_shift = { i_data[ 7:0],
453							{(DATA_WIDTH- 8){1'b0}} };
454				endcase
455	
456				if (OPT_LOCAL_BUS && (&i_addr[DATA_WIDTH-1:DATA_WIDTH-8]))
457				begin
458					wide_preshift = { {(BUS_WIDTH-DATA_WIDTH){1'b0}}, pre_shift };
459	
460					shifted_data = wide_preshift >> (8*i_addr[2-1:0]);
461				end else begin
462					wide_preshift = { pre_shift,
463							{(BUS_WIDTH-DATA_WIDTH){1'b0}} };
464	
465					shifted_data = wide_preshift >> (8*i_addr[WBLSB-1:0]);
466				end
467			end
468	
469			initial	o_wb_data = 0;
470			always @(posedge i_clk)
471			if (OPT_LOWPOWER && i_reset)
472				o_wb_data <= 0;
473			else if ((!o_busy || !i_wb_stall)
474				&& (!OPT_LOWPOWER || (i_pipe_stb && i_op[0])))
475			begin
476				if (!OPT_LOWPOWER)
477				begin
478					casez(i_op[2:1])
479					2'b0?: o_wb_data <= {(BUS_WIDTH/DATA_WIDTH){i_data}};
480					2'b10: o_wb_data <= {(BUS_WIDTH/16){i_data[15:0]}};
481					2'b11: o_wb_data <= {(BUS_WIDTH/ 8){i_data[ 7:0]}};
482					endcase
483				end else begin
484					o_wb_data <= shifted_data;
485				end
486			end else if (OPT_LOWPOWER && !i_wb_stall)
487				o_wb_data <= 0;
488			// }}}
489		end endgenerate
490		// }}}
491	
492		// Register return FIFO
493		// {{{
494		generate if (OPT_PIPE)
495		begin : OPT_PIPE_FIFO
496			// {{{
497			reg	[FIF_WIDTH-1:0]	fifo_data [0:((1<<OPT_FIFO_DEPTH)-1)];
498	
499			reg	[DP:0]		wraddr, rdaddr;
500	
501			always @(posedge i_clk)
502			if (i_pipe_stb)
503				fifo_data[wraddr[DP-1:0]]
504					<= { i_oreg[NAUX-2:0], i_op[2:1], i_addr[WBLSB-1:0] };
505	
506			always @(posedge i_clk)
507			if (i_pipe_stb)
508				gie <= i_oreg[NAUX-1];
509	
510	`ifdef	NO_BKRAM
511			reg	[FIF_WIDTH-1:0]	r_req_data, r_last_data;
512			reg			single_write;
513	
514			always @(posedge i_clk)
515				r_req_data <= fifo_data[rdaddr[DP-1:0]];
516	
517			always @(posedge i_clk)
518				single_write <= (rdaddr == wraddr)&&(i_pipe_stb);
519	
520			always @(posedge i_clk)
521			if (i_pipe_stb)
522				r_last_data <= { i_oreg[NAUX-2:0],
523							i_op[2:1], i_addr[WBLSB-1:0] };
524	
525			always @(*)
526			begin
527				req_data[NAUX+4-1] = gie;
528				// if ((r_svalid)||(state == DC_READ))
529				if (single_write)
530					req_data[FIF_WIDTH-1:0] = r_last_data;
531				else
532					req_data[FIF_WIDTH-1:0] = r_req_data;
533			end
534	
535			always @(*)
536				`ASSERT(req_data == fifo_data[rdaddr[DP-1:0]]);
537	`else
538			always @(*)
539				req_data[FIF_WIDTH-1:0] = fifo_data[rdaddr[DP-1:0]];
540			always @(*)
541				req_data[FIF_WIDTH] = gie;
542	`endif
543	
544			initial	wraddr = 0;
545			always @(posedge i_clk)
546			if ((i_reset)||((cyc)&&(i_wb_err)))
547				wraddr <= 0;
548			else if (i_pipe_stb)
549				wraddr <= wraddr + 1'b1;
550	
551			initial	rdaddr = 0;
552			always @(posedge i_clk)
553			if ((i_reset)||((cyc)&&(i_wb_err)))
554				rdaddr <= 0;
555			else if ((r_dvalid)||(r_svalid))
556				rdaddr <= rdaddr + 1'b1;
557			else if ((state == DC_WRITE)&&(i_wb_ack))
558				rdaddr <= rdaddr + 1'b1;
559			else if ((state == DC_READS)&&(i_wb_ack))
560				rdaddr <= rdaddr + 1'b1;
561	
562	`ifdef	FORMAL
563			reg	[AW-1:0]	f_fifo_addr [0:((1<<OPT_FIFO_DEPTH)-1)];
564			reg	[F_LGDEPTH-1:0]	f_last_wraddr;
565			reg	[FIF_WIDTH:0]	f_last_data;
566	
567			always @(*)
568			begin
569				f_fill = 0;
570				f_fill[DP:0] = wraddr - rdaddr;
571			end
572	
573			always @(*)
574				`ASSERT(f_fill <= { 1'b1, {(DP){1'b0}} });
575	
576			always @(*)
577			if ((r_dvalid)||(r_svalid))
578			begin
579				if (r_svalid)
580				begin
581					`ASSERT(f_fill == 1);
582				end else if (r_dvalid)
583				begin
584					`ASSERT(f_fill == 1);
585				end else
586					`ASSERT(f_fill == 0);
587			end else if (r_rd_pending)
588			begin
589				`ASSERT(f_fill == 1);
590			end else
591				`ASSERT(f_fill == npending);
592	
593	
594			initial	f_pc_pending = 0;
595			always @(posedge i_clk)
596			if (i_reset)
597				f_pc_pending <= 1'b0;
598			else if (i_pipe_stb)
599				f_pc_pending <= (!i_op[0])&&(i_oreg[3:1] == 3'h7);
600			else if (f_fill == 0)
601				f_pc_pending <= 1'b0;
602			//else if ((o_valid)&&(o_wreg[3:1] == 3'h7)&&(f_fill == 0))
603			//	f_pc_pending <= 1'b0;
604	
605			always @(posedge i_clk)
606			if (f_pc_pending)
607			begin
608				`ASSUME(!i_pipe_stb);
609			end
610	
611			always @(posedge i_clk)
612			if (state == DC_WRITE)
613			begin
614				`ASSERT(!f_pc_pending);
615			end
616	
617			always @(*)
618			begin
619				f_last_wraddr = 0;
620				f_last_wraddr[DP:0] = wraddr - 1'b1;
621			end
622	
623			assign	f_last_data = fifo_data[f_last_wraddr];
624	
625			always @(posedge i_clk)
626			if (r_rd_pending)
627			begin
628				`ASSERT(f_pc_pending == (f_last_data[1+WBLSB+2 +: 3] == 3'h7));
629				`ASSERT({ gie, f_last_data[2+WBLSB +: 4] } == f_last_reg);
630			end
631	
632	`define	INSPECT_FIFO
633			reg	[((1<<(DP+1))-1):0]	f_valid_fifo_entry;
634	
635			genvar	gk;
636			for(gk=0; gk<(1<<(DP+1)); gk=gk+1)
637			begin
638	
639				always @(*)
640				begin
641				f_valid_fifo_entry[gk] = 1'b0;
642				/*
643				if ((rdaddr[DP] != wraddr[DP])
644						&&(rdaddr[DP-1:0] == wraddr[DP-1:0]))
645					f_valid_fifo_entry[k] = 1'b1;
646				else */
647				if ((rdaddr < wraddr)&&(gk < wraddr)
648						&&(gk >= rdaddr))
649					f_valid_fifo_entry[gk] = 1'b1;
650				else if ((rdaddr > wraddr)&&(gk >= rdaddr))
651					f_valid_fifo_entry[gk] = 1'b1;
652				else if ((rdaddr > wraddr)&&(gk <  wraddr))
653					f_valid_fifo_entry[gk] = 1'b1;
654				end
655	
656	`ifdef	INSPECT_FIFO
657				wire	[FIF_WIDTH-1:0]	fifo_data_k;
658	
659				assign	fifo_data_k = fifo_data[gk[DP-1:0]];
660	
661				always @(*)
662				if (f_valid_fifo_entry[gk])
663				begin
664					if (!f_pc_pending)
665					begin
666						`ASSERT((o_wb_we)||(fifo_data_k[1+2+WBLSB +: 3] != 3'h7));
667					end else if (gk != f_last_wraddr)
668						`ASSERT(fifo_data_k[1+2+WBLSB +: 3] != 3'h7);
669				end
670	`endif // INSPECT_FIFO
671	
672			end
673	
674	`ifndef	INSPECT_FIFO
675			always @(posedge i_clk)
676			if ((r_rd_pending)&&(rdaddr[DP:0] != f_last_wraddr[DP-1]))
677				assume(req_data[1+2+WBLSB +: 3] != 3'h7);
678	`endif // INSPECT_FIFO
679	
680			//
681			//
682			//
683			always @(*)
684			begin
685				f_pending_addr[AW-1:0] = f_fifo_addr[rdaddr];
686				f_pending_addr[AW] = r_wb_cyc_lcl;
687			end
688	
689			//
690			//
691			//
692			always @(posedge i_clk)
693			if (i_pipe_stb)
694			begin
695				if (OPT_LOCAL_BUS && (&i_addr[DATA_WIDTH-1:DATA_WIDTH-8]))
696					f_fifo_addr[wraddr[DP-1:0]] <= { 1'b1, i_addr[2 +: AW] };
697				else
698					f_fifo_addr[wraddr[DP-1:0]] <= { 1'b0, i_addr[WBLSB +: AW] };
699			end
700	
701			always @(*)
702			begin
703				f_return_address[AW] = (o_wb_cyc_lcl);
704				f_return_address[AW-1:0] = f_fifo_addr[rdaddr];
705				if (state == DC_READC)
706					f_return_address[LS-1:0]
707					= (o_wb_addr[LS-1:0] - f_outstanding[LS-1:0]);
708			end
709	
710	`define	TWIN_WRITE_TEST
711	`ifdef	TWIN_WRITE_TEST
712					reg	[DP:0]		f_twin_next;
713			// Verilator lint_off UNDRIVEN
714			(* anyconst *)	reg	[DP:0]		f_twin_base;
715			(* anyconst *)	reg [AW+FIF_WIDTH-1:0]	f_twin_first,
716								f_twin_second;
717			// Verilator lint_on  UNDRIVEN
718			reg	f_twin_none, f_twin_single, f_twin_double, f_twin_last;
719			reg	f_twin_valid_one, f_twin_valid_two;
720	
721			always @(*)
722				f_twin_next = f_twin_base+1;
723	
724			always @(*)
725			begin
726				f_twin_valid_one = ((f_valid_fifo_entry[f_twin_base])
727					&&(f_twin_first == { f_fifo_addr[f_twin_base[DP-1:0]],
728							fifo_data[f_twin_base[DP-1:0]] }));
729				f_twin_valid_two = ((f_valid_fifo_entry[f_twin_next])
730					&&(f_twin_second == { f_fifo_addr[f_twin_next[DP-1:0]],
731							fifo_data[f_twin_next[DP-1:0]] }));
732			end
733	
734			always @(*)
735			begin
736				f_twin_none   =(!f_twin_valid_one)&&(!f_twin_valid_two);
737				f_twin_single =( f_twin_valid_one)&&(!f_twin_valid_two);
738				f_twin_double =( f_twin_valid_one)&&( f_twin_valid_two);
739				f_twin_last   =(!f_twin_valid_one)&&( f_twin_valid_two);
740			end
741	
742			always @(posedge i_clk)
743			if ((!f_past_valid)||($past(i_reset))||($past(cyc && i_wb_err)))
744			begin
745				`ASSERT(f_twin_none);
746			end else if ($past(f_twin_none))
747			begin
748				`ASSERT(f_twin_none || f_twin_single || f_twin_last);
749			end else if ($past(f_twin_single))
750			begin
751				`ASSERT(f_twin_none || f_twin_single || f_twin_double || f_twin_last);
