882			// }}}
883		end endgenerate
884		// }}}
885	
886		// BIG STATE machine: CYC, STB, c_v, state, etc
887		// {{{
888		initial	o_wb_addr    = 0;
889		initial	r_wb_cyc_gbl = 0;
890		initial	r_wb_cyc_lcl = 0;
891		initial	o_wb_stb_gbl = 0;
892		initial	o_wb_stb_lcl = 0;
893		initial	c_v = 0;
894		initial	cyc = 0;
895		initial	stb = 0;
896		initial	c_wr = 0;
897		initial	wr_cstb = 0;
898		initial	state = DC_IDLE;
899		initial	set_vflag = 1'b0;
900		always @(posedge i_clk)
901		if (i_reset)
902		begin
903			// {{{
904			c_v <= 0;
905			c_wr   <= 1'b0;
906			c_wsel  <= {(BUS_WIDTH/8){1'b1}};
907			r_wb_cyc_gbl <= 1'b0;
908			r_wb_cyc_lcl <= 1'b0;
909			o_wb_stb_gbl <= 0;
910			o_wb_stb_lcl <= 0;
911			o_wb_addr    <= 0;
912			wr_cstb <= 1'b0;
913			last_line_stb <= 1'b0;
914			end_of_line <= 1'b0;
915			cyc <= 1'b0;
916			stb <= 1'b0;
917			state <= DC_IDLE;
918			set_vflag <= 1'b0;
919			// }}}
920		end else begin
921			// By default, update the cache from the write 1-clock ago
922			// c_wr <= (wr_cstb)&&(wr_wtag == wr_vtag);
923			// c_waddr <= wr_addr[(CS-1):0];
924			c_wr <= 0;
925	
926			set_vflag <= 1'b0;
927			if (!cyc && set_vflag)
928				c_v[c_waddr[(CS-1):LS]] <= 1'b1;
929	
930			wr_cstb <= 1'b0;
931	
932			// end_of_line
933			// {{{
934			// Verilator coverage_off
935			if (LS <= 0)
936				end_of_line <= 1'b1;
937			// Verilator coverage_on
938			else if (!cyc)
939				end_of_line <= 1'b0;
940			else if (!end_of_line)
941			begin
942				if (i_wb_ack)
943					end_of_line
944					<= (c_waddr[(LS-1):0] == {{(LS-2){1'b1}},2'b01});
945				else
946					end_of_line
947					<= (c_waddr[(LS-1):0]=={{(LS-1){1'b1}}, 1'b0});
948			end
949			// }}}
950	
951			// last_line_stb
952			// {{{
953			if (!cyc || !stb || (OPT_LOWPOWER && state != DC_READC))
954				last_line_stb <= (LS <= 0);
955			// Verilator coverage_off
956			else if (!i_wb_stall && (LS <= 1))
957				last_line_stb <= 1'b1;
958			// Verilator coverage_on
959			else if (!i_wb_stall)
960				last_line_stb <= (o_wb_addr[(LS-1):1]=={(LS-1){1'b1}});
961			else
962				last_line_stb <= (o_wb_addr[(LS-1):0]=={(LS){1'b1}});
963			// }}}
964	
965			//
966			//
967			case(state)
968			DC_IDLE: begin
969				// {{{
970				o_wb_we <= 1'b0;
971	
972				cyc <= 1'b0;
973				stb <= 1'b0;
974	
975				r_wb_cyc_gbl <= 1'b0;
976				r_wb_cyc_lcl <= 1'b0;
977				o_wb_stb_gbl <= 1'b0;
978				o_wb_stb_lcl <= 1'b0;
979	
980				in_cache <= (i_op[0])&&(w_cachable);
981				if ((i_pipe_stb)&&(i_op[0]))
982				begin // Write  operation
983					// {{{
984					state <= DC_WRITE;
985					if (OPT_LOCAL_BUS && (&i_addr[DATA_WIDTH-1:DATA_WIDTH-8]))
986						o_wb_addr <= i_addr[2 +: AW];
987					else
988						o_wb_addr <= i_addr[WBLSB +: AW];
989	
990					o_wb_we <= 1'b1;
991	
992					cyc <= 1'b1;
993					stb <= 1'b1;
994	
995					if (OPT_LOCAL_BUS)
996					begin
997					r_wb_cyc_gbl <= (i_addr[DATA_WIDTH-1:DATA_WIDTH-8]!=8'hff);
998					r_wb_cyc_lcl <= (i_addr[DATA_WIDTH-1:DATA_WIDTH-8]==8'hff);
999					o_wb_stb_gbl <= (i_addr[DATA_WIDTH-1:DATA_WIDTH-8]!=8'hff);
1000					o_wb_stb_lcl <= (i_addr[DATA_WIDTH-1:DATA_WIDTH-8]==8'hff);
1001					end else begin
1002						r_wb_cyc_gbl <= 1'b1;
1003						o_wb_stb_gbl <= 1'b1;
1004					end
1005					// }}}
1006				end else if (r_cache_miss)
1007				begin // Cache miss
1008					state <= DC_READC;
1009					o_wb_addr <= { r_ctag, {(LS){1'b0}} };
1010	
1011					c_waddr <= { r_ctag[CS-LS-1:0], {(LS){1'b0}} }-1'b1;
1012					cyc <= 1'b1;
1013					stb <= 1'b1;
1014					r_wb_cyc_gbl <= 1'b1;
1015					o_wb_stb_gbl <= 1'b1;
1016				end else if ((i_pipe_stb)&&(!w_cachable))
1017				begin // Read non-cachable memory area
1018					state <= DC_READS;
1019	
1020					if (OPT_LOCAL_BUS && (&i_addr[DATA_WIDTH-1:DATA_WIDTH-8]))
1021						o_wb_addr <= i_addr[2 +: AW];
1022					else
1023						o_wb_addr <= i_addr[WBLSB +: AW];
1024	
1025					cyc <= 1'b1;
1026					stb <= 1'b1;
1027					if (OPT_LOCAL_BUS)
1028					begin
1029					r_wb_cyc_gbl <= (i_addr[DATA_WIDTH-1:DATA_WIDTH-8]!=8'hff);
1030					r_wb_cyc_lcl <= (i_addr[DATA_WIDTH-1:DATA_WIDTH-8]==8'hff);
1031					o_wb_stb_gbl <= (i_addr[DATA_WIDTH-1:DATA_WIDTH-8]!=8'hff);
1032					o_wb_stb_lcl <= (i_addr[DATA_WIDTH-1:DATA_WIDTH-8]==8'hff);
1033					end else begin
1034					r_wb_cyc_gbl <= 1'b1;
1035					o_wb_stb_gbl <= 1'b1;
1036					end
1037				end // else we stay idle
1038				end
1039				// }}}
1040			DC_READC: begin
1041				// {{{
1042				// We enter here once we have committed to reading
1043				// data into a cache line.
1044				if (stb && !i_wb_stall)
1045				begin
1046					stb <= (!last_line_stb);
1047					o_wb_stb_gbl <= (!last_line_stb);
1048					o_wb_addr[(LS-1):0] <= o_wb_addr[(LS-1):0]+1'b1;
1049	
1050					if (OPT_LOWPOWER && last_line_stb)
1051						o_wb_addr <= 0;
1052				end
1053	
1054				if (i_wb_ack)
1055					c_v[r_cline] <= 1'b0;
1056	
1057				c_wr    <= (i_wb_ack);
1058				c_wdata <= i_wb_data;
1059				c_waddr <= c_waddr+(i_wb_ack ? 1:0);
1060				c_wsel  <= {(BUS_WIDTH/8){1'b1}};
1061	
1062				set_vflag <= !i_wb_err;
1063				// if (i_wb_ack)
1064				//	c_vtags[r_addr[(CS-1):LS]]
1065				//			<= r_addr[(AW-1):LS];
1066	
1067				if ((i_wb_ack && end_of_line)|| i_wb_err)
1068				begin
1069					state          <= DC_IDLE;
1070					cyc <= 1'b0;
1071					stb <= 1'b0;
1072					r_wb_cyc_gbl <= 1'b0;
1073					r_wb_cyc_lcl <= 1'b0;
1074					o_wb_stb_gbl <= 1'b0;
1075					o_wb_stb_lcl <= 1'b0;
1076					//
1077					if (OPT_LOWPOWER)
1078						o_wb_addr <= 0;
1079				end end
1080				// }}}
1081			DC_READS: begin
1082				// {{{
1083				// We enter here once we have committed to reading
1084				// data that cannot go into a cache line
1085				if ((!i_wb_stall)&&(!i_pipe_stb))
1086				begin
1087					stb <= 1'b0;
1088					o_wb_stb_gbl <= 1'b0;
1089					o_wb_stb_lcl <= 1'b0;
1090					if (OPT_LOWPOWER)
1091						o_wb_addr <= 0;
1092				end
1093	
1094				if ((!i_wb_stall)&&(i_pipe_stb))
1095				begin
1096					if (OPT_LOCAL_BUS && (&i_addr[DATA_WIDTH-1:DATA_WIDTH-8]))
1097						o_wb_addr <= i_addr[2 +: AW];
1098					else
1099						o_wb_addr <= i_addr[WBLSB +: AW];
1100				end
1101	
1102				c_wr <= 1'b0;
1103	
1104				if (((i_wb_ack)&&(last_ack))||(i_wb_err))
1105				begin
1106					state        <= DC_IDLE;
1107					cyc          <= 1'b0;
1108					stb          <= 1'b0;
1109					r_wb_cyc_gbl <= 1'b0;
1110					r_wb_cyc_lcl <= 1'b0;
1111					o_wb_stb_gbl <= 1'b0;
1112					o_wb_stb_lcl <= 1'b0;
1113					if (OPT_LOWPOWER)
1114						o_wb_addr <= 0;
1115				end end
1116				// }}}
1117			DC_WRITE: begin
1118				// {{{
1119				c_wr    <= o_wb_stb_gbl && (c_v[o_wb_addr[CS-1:LS]])
1120					// &&(c_vtags[o_wb_addr[CS-1:LS]]==o_wb_addr[AW-1:LS]);
1121					&&(r_itag==o_wb_addr[AW-1:LS]);
1122				c_wdata <= o_wb_data;
1123				c_waddr <= r_addr[CS-1:0];
1124				c_wsel  <= o_wb_sel;
1125	
1126				if ((!i_wb_stall)&&(!i_pipe_stb))
1127				begin
1128					stb          <= 1'b0;
1129					o_wb_stb_gbl <= 1'b0;
1130					o_wb_stb_lcl <= 1'b0;
1131					if (OPT_LOWPOWER)
1132						o_wb_addr <= 0;
1133				end
1134	
1135				wr_cstb  <= (stb)&&(!i_wb_stall)&&(in_cache);
1136	
1137				if (i_pipe_stb && !i_wb_stall)
1138				begin
1139					if (OPT_LOCAL_BUS && (&i_addr[DATA_WIDTH-1:DATA_WIDTH-8]))
1140						o_wb_addr <= i_addr[2 +: AW];
1141					else
1142						o_wb_addr <= i_addr[WBLSB +: AW];
1143				end
1144	
1145				if (((i_wb_ack)&&(last_ack)
1146							&&((!OPT_PIPE)||(!i_pipe_stb)))
1147					||(i_wb_err))
1148				begin
1149					state        <= DC_IDLE;
1150					cyc          <= 1'b0;
1151					stb          <= 1'b0;
1152					r_wb_cyc_gbl <= 1'b0;
1153					r_wb_cyc_lcl <= 1'b0;
1154					o_wb_stb_gbl <= 1'b0;
1155					o_wb_stb_lcl <= 1'b0;
1156					if (OPT_LOWPOWER)
1157						o_wb_addr <= 0;
1158				end end
1159				// }}}
1160			endcase
1161	
1162			if (i_clear)
1163				c_v <= 0;
1164		end
1165	
1166		always @(posedge i_clk)
1167		if (state == DC_READC && i_wb_ack)
1168			c_vtags[r_addr[(CS-1):LS]] <= r_addr[(AW-1):LS];
1169		// }}}
1170	
1171		// wr_addr
1172		// {{{
1173		always @(posedge i_clk)
1174		if (!cyc)
1175		begin
1176			wr_addr <= r_addr[(CS-1):0];
1177			if ((!i_pipe_stb || !i_op[0])&&(r_cache_miss))
1178				wr_addr[LS-1:0] <= 0;
1179		end else if (i_wb_ack)
1180			wr_addr <= wr_addr + 1'b1;
1181		else
1182			wr_addr <= wr_addr;
1183		// }}}
1184	
1185	
1186		// npending
1187		// {{{
1188		// npending is the number of outstanding (non-cached) read or write
1189		// requests.  We only keep track of npending if we are running in a
1190		// piped fashion, i.e. if OPT_PIPE, and so need to keep track of
1191		// possibly multiple outstanding transactions
1192		initial	npending = 0;
1193		always @(posedge i_clk)
1194		if ((i_reset)||(!OPT_PIPE)
1195				||((cyc)&&(i_wb_err))
1196				||((!cyc)&&(!i_pipe_stb))
1197				||(state == DC_READC))
1198			npending <= 0;
1199		else if (r_svalid)
1200			npending <= (i_pipe_stb) ? 1:0;
1201		else case({ (i_pipe_stb), (cyc)&&(i_wb_ack) })
1202		2'b01: npending <= npending - 1'b1;
1203		2'b10: npending <= npending + 1'b1;
1204		default: begin end
1205		endcase
1206	
1207	`ifdef	FORMAL
1208		always @(*)
1209			`ASSERT(npending <= { 1'b1, {(DP){1'b0}} });
1210	`endif
1211		// }}}
1212	
1213		// last_ack
1214		// {{{
1215		initial	last_ack = 1'b0;
1216		always @(posedge i_clk)
1217		if (i_reset)
1218			last_ack <= 1'b0;
1219		else if (state == DC_IDLE)
1220		begin
1221			last_ack <= 1'b0;
1222			if ((i_pipe_stb)&&(i_op[0]))
1223				last_ack <= 1'b1;
1224			else if (r_cache_miss)
1225				last_ack <= (LS == 0);
1226			else if ((i_pipe_stb)&&(!w_cachable))
1227				last_ack <= 1'b1;
1228		end else if (state == DC_READC)
1229		begin
1230			if (i_wb_ack)
1231				last_ack <= last_ack || (&wr_addr[LS-1:1]);
1232			else
1233				last_ack <= last_ack || (&wr_addr[LS-1:0]);
1234		end else case({ (i_pipe_stb), (i_wb_ack) })
1235		2'b01: last_ack <= (npending <= 2);
1236		2'b10: last_ack <= (!cyc)||(npending == 0);
1237		default: begin end
1238		endcase
1239		// }}}
1240	
1241		//
1242		// Writes to the cache
1243		// {{{
1244		// These have been made as simple as possible.  Note that the c_wr
1245		// line has already been determined, as have the write value and address
1246		// on the last clock.  Further, this structure is defined to match the
1247		// block RAM design of as many architectures as possible.
1248		//
1249		always @(posedge i_clk)
1250		if (c_wr)
1251		begin
1252			for(ik=0; ik<BUS_WIDTH/8; ik=ik+1)
1253			if (c_wsel[ik])
1254				c_mem[c_waddr][ik *8 +: 8] <= c_wdata[ik * 8 +: 8];
1255		end
1256		// }}}
1257	
1258		//
1259		// Reads from the cache
1260		// {{{
1261		// Some architectures require that all reads be registered.  We
1262		// accomplish that here.  Whether or not the result of this read is
1263		// going to be our output will need to be determined with combinatorial
1264		// logic on the output.
1265		//
1266		generate if (OPT_DUAL_READ_PORT)
1267		begin : GEN_DUAL_READ_PORT
1268	
1269			always @(posedge i_clk)
1270				cached_iword <= c_mem[i_caddr];
1271	
1272			always @(posedge i_clk)
1273				cached_rword <= c_mem[r_caddr];
1274	
1275		end else begin : GEN_SHARED_READ_PORT
1276	
1277			always @(posedge i_clk)
1278				cached_rword <= c_mem[(o_busy) ? r_caddr : i_caddr];
1279	
1280			always @(*)
1281				cached_iword = cached_rword;
1282	
1283		end endgenerate
1284		// }}}
1285	
1286		// o_data, pre_data
1287		// {{{
1288		// o_data can come from one of three places:
1289		// 1. The cache, assuming the data was in the last cache line
1290		// 2. The cache, second clock, assuming the data was in the cache at all
1291		// 3. The cache, after filling the cache
1292		// 4. The wishbone state machine, upon reading the value desired.
1293	
1294		always @(*)
1295		if (r_svalid)
1296			pre_data = cached_iword;
1297		else if (state == DC_READS)
