1826			end else if (!f_const_addr[AW]
1827				&& (!OPT_LOCAL_BUS
1828					|| !(&i_addr[DATA_WIDTH-1:DATA_WIDTH-8]))
1829				&& (i_addr[WBLSB +: AW] == f_const_addr[AW-1:0]))
1830			begin // Global bus word
1831				for(ik=0; ik<BUS_WIDTH/8; ik=ik+1)
1832				if (f_shifted_sel[ik])
1833					f_const_data[8*ik +: 8] <= f_shifted_data[8*ik +: 8];
1834			end
1835		end
1836		// }}}
1837	
1838	
1839		// Insure the cache and bus both have an accurate/valid copy of the data
1840		// {{{
1841		always @(posedge i_clk)
1842		if ((f_past_valid)&&(!i_reset)&&(!f_const_buserr))
1843		begin
1844			// Is this a write to our special address?
1845			if (cyc && o_wb_we && f_stb
1846					&&(o_wb_addr[AW-1:0] == f_const_addr[AW-1:0])
1847					&&( o_wb_stb_lcl == f_const_addr[AW]))
1848			begin
1849				// Only the updated data value should be written to the
1850				// bus
1851				// {{{
1852				if (f_const_addr[AW])
1853				begin
1854					for(ik=0; ik<DATA_WIDTH/8; ik=ik+1)
1855					if (f_stb && o_wb_sel[ik])
1856						`ASSERT(o_wb_data[ik*8 +: 8]==f_const_data[ik*8 +: 8]);
1857				end else begin
1858					for(ik=0; ik<BUS_WIDTH/8; ik=ik+1)
1859					if (f_stb && o_wb_sel[ik])
1860						`ASSERT(o_wb_data[ik*8 +: 8]==f_const_data[ik*8 +: 8]);
1861				end
1862				// }}}
1863	
1864				// Check the data written into the cache for validity
1865				// {{{
1866				if (!f_const_addr[AW] && c_v[f_const_tag_addr]
1867					&& (f_ctag_here == o_wb_addr[AW-1:LS]))
1868				begin
1869					for(ik=0; ik<BUS_WIDTH/8; ik=ik+1)
1870					if (!o_wb_sel[ik] && !c_wsel[ik])
1871						`ASSERT(f_cmem_here[8*ik +: 8]==f_const_data[8*ik +: 8]);
1872				// }}}
1873	
1874				end
1875			// Otherwise, if this is a valid address, *and* it is in the
1876			// cache ...
1877			end else if (!f_const_addr[AW] && c_v[f_const_tag_addr]
1878				&&(f_ctag_here ==f_const_addr[AW-1:LS]))
1879			begin
1880				// If ...
1881				//   1. Our magic address is cachable
1882				//   2. Our magic address is associated with a valid
1883				//		cache line
1884				//   3. The cache tag matches our magic address
1885				// {{{
1886	
1887				// if ($past(cyc && i_wb_err))
1888				// begin
1889					// Ignore what happens on an error, the result
1890					// becomes undefined anyway
1891				// end else
1892				if (c_wr &&(c_waddr[CS-1:0] == f_const_addr[CS-1:0]))
1893				begin
1894					//
1895					// If we are writing to this valid cache line
1896					// {{{
1897					for(ik=0; ik<BUS_WIDTH/8; ik=ik+1)
1898					if (c_wsel[ik] && $past(o_wb_cyc_gbl))
1899					begin
1900						`ASSERT(c_wdata[8*ik +: 8]
1901								== f_const_data[8*ik +: 8]);
1902					end else
1903						`ASSERT(f_cmem_here[8*ik +: 8]
1904								== f_const_data[8*ik +: 8]);
1905					// }}}
1906				end else
1907					// Else, we assert the correct value is already
1908					// in the cache
1909					`ASSERT(f_cmem_here == f_const_data);
1910				// }}}
1911			end
1912		end
1913		// }}}
1914	
1915		// When reading a cache line, assert the correct value has been read
1916		// if we've passed that aprt of our read
1917		// {{{
1918		always @(posedge i_clk)
1919		if ((f_past_valid)&&(state == DC_READC))
1920		begin
1921			`ASSERT(f_return_address[AW-1:LS] == r_ctag);
1922			`ASSERT(f_wb_tag == r_ctag);
1923			if ((r_ctag == f_const_tag)
1924				&&(!c_v[f_const_tag_addr])
1925				&&(f_const_addr[AW] == r_wb_cyc_lcl)
1926				&&(f_nacks > f_const_addr[LS-1:0]))
1927			begin
1928				// We are reading the cache line containing our
1929				// constant address f_const_addr.  Make sure the data
1930				// is correct.
1931				if ((c_wr)&&(c_waddr[CS-1:0] == f_const_addr[CS-1:0]))
1932				begin
1933					`ASSERT(c_wdata == f_const_data);
1934				end else
1935					`ASSERT(f_cmem_here == f_const_data);
1936			end
1937	
1938			if (!i_reset && f_nacks > 0)
1939				`ASSERT(!c_v[r_cline]);
1940		end
1941		// }}}
1942	
1943		always @(posedge i_clk)
1944		if ((state == DC_READC)&&(f_nacks > 0))
1945		begin
1946			`ASSERT(c_vtags[wb_start[(CS-1):LS]] <= wb_start[(AW-1):LS]);
1947			`ASSERT(c_vtags[wb_start[(CS-1):LS]] <= r_addr[AW-1:LS]);
1948		end
1949	
1950		always @(*)
1951		begin
1952			// f_cache_waddr[AW-1:LS] = c_vtags[c_waddr[CS-1:CS-LS]];
1953			f_cache_waddr[AW-1:LS] = wb_start[AW-1:LS];
1954			f_cache_waddr[CS-1: 0] = c_waddr[CS-1:0];
1955		end
1956	
1957	
1958		always @(posedge i_clk)
1959		if ((f_past_valid)&&(state == DC_READC))
1960		begin
1961			if ((c_wr)&&(c_waddr[LS-1:0] != 0)&&(f_this_cache_waddr))
1962				`ASSERT(c_wdata == f_const_data);
1963		end
1964	
1965	//	always @(posedge i_clk)
1966	//	if ((OPT_PIPE)&&(o_busy)&&(i_pipe_stb))
1967	//		`ASSUME(i_op[0] == o_wb_we);
1968	
1969		initial	f_pending_rd = 0;
1970		always @(posedge i_clk)
1971		if (i_reset)
1972			f_pending_rd <= 0;
1973		else if (i_pipe_stb)
1974			f_pending_rd <= (!i_op[0]);
1975		else if ((o_valid)&&((!OPT_PIPE)
1976			||((state != DC_READS)&&(!r_svalid)&&(!$past(i_pipe_stb)))))
1977			f_pending_rd <= 1'b0;
1978	
1979		always @(*)
1980		if ((state == DC_READC)&&(!f_stb))
1981			`ASSERT(f_nreqs == (1<<LS));
1982	
1983		always @(*)
1984		if ((state == DC_READC)&&(f_stb))
1985			`ASSERT(f_nreqs == { 1'b0, o_wb_addr[LS-1:0] });
1986	
1987		always @(posedge i_clk)
1988		if (state == DC_READC)
1989		begin
1990			if (f_stb)
1991				assert(r_addr[AW-1:LS] == o_wb_addr[AW-1:LS]);
1992			if (($past(i_wb_ack))&&(!$past(f_stb)))
1993			begin
1994				`ASSERT(f_nacks-1 == { 1'b0, c_waddr[LS-1:0] });
1995			end else if (f_nacks > 0)
1996			begin
1997				`ASSERT(f_nacks-1 == { 1'b0, c_waddr[LS-1:0] });
1998				`ASSERT(c_waddr[CS-1:LS] == r_addr[CS-1:LS]);
1999			end else begin
2000				`ASSERT(c_waddr[CS-1:LS] == r_addr[CS-1:LS]-1'b1);
2001				`ASSERT(&c_waddr[LS-1:0]);
2002			end
2003		end
2004	
2005		always @(*)
2006		if (r_rd_pending)
2007			`ASSERT(r_addr == f_pending_addr[AW-1:0]);
2008	
2009		always @(*)
2010		if (f_pending_addr[AW])
2011		begin
2012			`ASSERT(state != DC_READC);
2013			`ASSERT((!o_wb_we)||(!o_wb_cyc_gbl));
2014		end
2015	
2016		reg	[BUS_WIDTH-1:0]	f_shift_const_data;
2017	
2018		always @(posedge i_clk)
2019		begin
2020			if (f_const_addr[AW])
2021				f_shift_const_data = { f_const_data[31:0], {(BUS_WIDTH-DATA_WIDTH){1'b0}} } << (8*req_data[2-1:0]);
2022			else
2023				f_shift_const_data = f_const_data << (8*req_data[WBLSB-1:0]);
2024		end
2025	
2026		always @(posedge i_clk)
2027		if ((f_past_valid)&&(o_valid)&&($past(f_pending_addr) == f_const_addr))
2028		begin
2029			if (f_const_buserr)
2030			begin
2031				`ASSERT(o_err);
2032			end else if (f_pending_rd)
2033			begin
2034				casez($past(req_data[WBLSB +: 2]))
2035				4'b0?: `ASSERT(o_data ==f_shift_const_data[BUS_WIDTH-1:BUS_WIDTH-32]);
2036				4'b10: `ASSERT(o_data =={16'h00,f_shift_const_data[BUS_WIDTH-1:BUS_WIDTH-16]});
2037				4'b11: `ASSERT(o_data =={24'h00,f_shift_const_data[BUS_WIDTH-1:BUS_WIDTH- 8]});
2038				endcase
2039			end
2040		end
2041	
2042		// #1. Assume this return matches our chosen data
2043		// {{{
2044		always @(*)
2045		if ((f_cyc)&&(
2046			((state == DC_READC)
2047				&&(f_return_address[AW-1:LS] == f_const_addr[AW-1:LS]))
2048			||(f_this_return)))
2049		begin
2050			if (f_const_buserr)
2051			begin
2052				assume(!i_wb_ack);
2053			end else begin
2054				assume(!i_wb_err);
2055				assume(i_wb_data == f_const_data);
2056			end
2057		end
2058		// }}}
2059	
2060		always @(posedge i_clk)
2061		if ((f_past_valid)&&(last_tag == f_const_tag)&&(f_const_buserr)
2062				&&(!f_const_addr[AW]))
2063			`ASSERT(!last_tag_valid);
2064	
2065		// Chosen address is invalid: bus error properties
2066		// {{{
2067		always @(*)
2068		if (f_const_buserr)
2069		begin
2070			`ASSERT((!c_v[f_const_tag_addr])||(f_const_addr[AW])
2071				||(f_ctag_here != f_const_tag));
2072	
2073			if ((state == DC_READC)&&(wb_start[AW-1:LS] == f_const_tag))
2074			begin
2075				`ASSERT(f_nacks <= f_const_tag[LS-1:0]);
2076				if (f_nacks == f_const_tag[LS-1:0])
2077					assume(!i_wb_ack);
2078			end
2079		end
2080		// }}}
2081	
2082		/*
2083		// ?? why was I assuming this again?
2084		always @(*)
2085		if (f_cval_in_cache)
2086		begin
2087			assume((!i_wb_err)
2088				||(!i_pipe_stb)
2089				||(f_const_addr[AW-1:0] != i_addr[WBLSB +: AW]));
2090		end
2091		*/
2092	
2093	`endif	// DCACHE
2094		// }}}
2095		////////////////////////////////////////////////////////////////////////
2096		//
2097		// Checking the lock
2098		// {{{
2099		////////////////////////////////////////////////////////////////////////
2100		//
2101		//
2102		always @(*)
2103			`ASSERT((!lock_gbl)||(!lock_lcl));
2104		always @(*)
2105		if (!OPT_LOCK)
2106			`ASSERT((!lock_gbl)&&(!lock_lcl));
2107		// }}}
2108		////////////////////////////////////////////////////////////////////////
2109		//
2110		// State based properties
2111		// {{{
2112		////////////////////////////////////////////////////////////////////////
2113		//
2114		//
2115		reg	[F_LGDEPTH-1:0]	f_rdpending;
2116		wire			f_wb_cachable;
2117	
2118		// f_rdpending
2119		// {{{
2120		initial	f_rdpending = 0;
2121		always @(posedge i_clk)
2122		if ((i_reset)||(o_err))
2123			f_rdpending <= 0;
2124		else case({ (i_pipe_stb)&&(!i_op[0]), o_valid })
2125		2'b01: f_rdpending <= f_rdpending - 1'b1;
2126		2'b10: f_rdpending <= f_rdpending + 1'b1;
2127		default: begin end
2128		endcase
2129		// }}}
2130	
2131		iscachable #(
2132			// {{{
2133			.ADDRESS_WIDTH(AW+WBLSB)
2134			// }}}
2135		) f_chkwb_addr({ r_addr, {(WBLSB){1'b0}} }, f_wb_cachable);
2136	
2137	
2138		always @(*)
2139		if (state == DC_IDLE)
2140		begin
2141			`ASSERT(!r_wb_cyc_gbl);
2142			`ASSERT(!r_wb_cyc_lcl);
2143	
2144			`ASSERT(!cyc);
2145	
2146			if ((r_rd_pending)||(r_dvalid)||(r_svalid))
2147				`ASSERT(o_busy);
2148	
2149			if (!OPT_PIPE)
2150			begin
2151				if (r_rd_pending)
2152				begin
2153					`ASSERT(o_busy);
2154				end else if (r_svalid)
2155				begin
2156					`ASSERT(o_busy);
2157				end else if (o_valid)
2158				begin
2159					`ASSERT(!o_busy);
2160				end else if (o_err)
2161				begin
2162					`ASSERT(!o_busy);
2163				end
2164			end
2165		end else begin
2166			`ASSERT(o_busy);
2167			`ASSERT(cyc);
2168		end
2169	
2170	
2171	
2172		always @(posedge i_clk)
2173		if (state == DC_IDLE)
2174		begin
2175			if (r_svalid)
2176			begin
2177				`ASSERT(!r_dvalid);
2178				`ASSERT(!r_rd_pending);
2179				if (!OPT_PIPE)
2180				begin
2181					`ASSERT(!o_valid);
2182				end else if (o_valid)
2183					`ASSERT(f_rdpending == 2);
2184			end
2185	
2186			if (r_dvalid)
2187			begin
2188				`ASSERT(!r_rd_pending);
2189				`ASSERT(npending == 0);
2190				`ASSERT(f_rdpending == 1);
2191			end
2192	
2193			if (r_rd_pending)
2194			begin
2195				if ((OPT_PIPE)&&(o_valid))
2196				begin
2197					`ASSERT(f_rdpending <= 2);
2198				end else
2199					`ASSERT(f_rdpending == 1);
2200	
2201			end else if ((OPT_PIPE)&&(o_valid)&&($past(r_dvalid|r_svalid)))
2202			begin
2203				`ASSERT(f_rdpending <= 2);
2204			end else
2205				`ASSERT(f_rdpending <= 1);
2206		end
2207	
2208		always @(posedge i_clk)
2209		if (state == DC_READC)
2210		begin
2211			`ASSERT( o_wb_cyc_gbl);
2212			`ASSERT(!o_wb_cyc_lcl);
2213			`ASSERT(!o_wb_we);
2214			`ASSERT(f_wb_cachable);
2215			`ASSERT(!lock_gbl);
2216			`ASSERT(!lock_lcl);
2217	
2218			`ASSERT(r_rd_pending);
2219			`ASSERT(r_cachable);
2220			if (($past(cyc))&&(!$past(o_wb_stb_gbl)))
2221			begin
2222				`ASSERT(!o_wb_stb_gbl);
2223			end
2224	
2225			if ((OPT_PIPE)&&(o_valid))
2226			begin
2227				`ASSERT(f_rdpending == 2);
2228			end else
2229				`ASSERT(f_rdpending == 1);
2230		end
2231	
2232		always @(*)
2233		if (state == DC_READS)
2234		begin
2235			`ASSERT(!o_wb_we);
2236	
2237			if (OPT_PIPE)
2238			begin
2239				if (o_valid)
2240				begin
2241					`ASSERT(({ 1'b0, f_rdpending } == npending + 1)
2242						||({ 1'b0, f_rdpending } == npending));
2243				end else
2244					`ASSERT({ 1'b0, f_rdpending } == npending);
2245			end
2246		end else if (state == DC_WRITE)
2247			`ASSERT(o_wb_we);
2248	
2249		always @(posedge i_clk)
2250		if ((state == DC_READS)||(state == DC_WRITE))
2251		begin
2252			`ASSERT(o_wb_we == (state == DC_WRITE));
2253			`ASSERT(!r_rd_pending);
2254			if (o_wb_we)
2255				`ASSERT(f_rdpending == 0);
2256	
2257			if (OPT_PIPE)
2258			begin
2259				casez({ $past(i_pipe_stb), f_stb })
2260				2'b00: `ASSERT(npending == { 1'b0, f_outstanding});
2261				2'b1?: `ASSERT(npending == { 1'b0, f_outstanding} + 1);
2262				2'b01: `ASSERT(npending == { 1'b0, f_outstanding} + 1);
2263				endcase
2264	
2265				if (state == DC_WRITE)
2266					`ASSERT(!o_valid);
2267			end else
2268				`ASSERT(f_outstanding <= 1);
2269		end
2270	
2271		always @(*)
2272		if (OPT_PIPE)
2273		begin
2274			`ASSERT(f_rdpending <= 2);
2275		end else
2276			`ASSERT(f_rdpending <= 1);
2277	
2278		always @(posedge i_clk)
2279		if ((!OPT_PIPE)&&(o_valid))
2280		begin
2281			`ASSERT(f_rdpending == 1);
2282		end else if (o_valid)
2283			`ASSERT(f_rdpending >= 1);
2284	
2285	
2286		always @(*)
2287		if ((!o_busy)&&(!o_err)&&(!o_valid))
2288			`ASSERT(f_rdpending == 0);
2289	
2290		always @(*)
2291			`ASSERT(cyc == ((r_wb_cyc_gbl)||(r_wb_cyc_lcl)));
2292	
2293		always @(*)
2294		if ((!i_reset)&&(f_nreqs == f_nacks)&&(!f_stb))
2295			`ASSERT(!cyc);
2296	
2297		always @(posedge i_clk)
2298		if ((f_past_valid)&&($past(o_err)))
2299		begin
2300			`ASSUME(!i_lock);
2301		end else if ((f_past_valid)&&(OPT_LOCK)&&($past(i_lock))
2302				&&((!$past(o_valid)) || ($past(i_pipe_stb))))
2303			`ASSUME($stable(i_lock));
2304	
2305		// }}}
